            is_regex=False
            if prev is None: is_regex=True
            elif prev.kind=="punct" and prev.value not in (")","]","}"): is_regex=True
            elif prev.kind=="name" and prev.value in ("return","case","typeof","in","of","new","delete","void","instanceof","export","default"): is_regex=True
            if is_regex:
                advance(); pattern=""; in_class=False
                while i<n:
                    ch=src[i]
                    if ch=="\\":
                        pattern+=ch; advance()
                        if i<n: pattern+=src[i]; advance()
                        continue
                    if ch=="[": in_class=True
                    if ch=="]": in_class=False
                    if ch=="/" and not in_class:
                        advance(); break
                    if ch=="\n": break
                    pattern+=ch; advance()
                flags=""
                while i<n and (src[i].isalpha()):
                    flags+=src[i]; advance()
                toks.append(Tok("regex", pattern, start_line, start_col, flags)); prev=toks[-1]; continue
            # fall through punct
        if c.isalpha() or c in "_$":
            j=i
            while i<n and (src[i].isalnum() or src[i] in "_$"): advance()
            toks.append(Tok("name", src[j:i], start_line, start_col)); prev=toks[-1]; continue
        if c.isdigit() or (c=="." and i+1<n and src[i+1].isdigit()):
            j=i
            # hex etc
            if src.startswith(("0x","0X"), i):
                advance(2)
                while i<n and (src[i].isdigit() or src[i] in "abcdefABCDEF"): advance()
                toks.append(Tok("number", int(src[j:i],16), start_line, start_col))
            else:
                while i<n and (src[i].isdigit() or src[i]=="_"): advance()
                if i<n and src[i]=="." :
                    advance()
                    while i<n and src[i].isdigit(): advance()
                if i<n and src[i] in "eE":
                    advance()
                    if i<n and src[i] in "+-": advance()
                    while i<n and src[i].isdigit(): advance()
                raw=src[j:i].replace("_","")
                val=float(raw) if ("." in raw or "e" in raw or "E" in raw) else int(raw)
                if isinstance(val,float) and val.is_integer(): val=int(val)
                toks.append(Tok("number", val, start_line, start_col))
            prev=toks[-1]; continue
        matched=None
        for p in PUNCTS:
            if src.startswith(p,i): matched=p; break
        if matched:
            advance(len(matched)); toks.append(Tok("punct", matched, start_line, start_col)); prev=toks[-1]; continue
        raise JSError(f"Unexpected token '{c}'", "SyntaxError")
    toks.append(Tok("eof", None, line, col))
    return toks

# ---------------- Parser ----------------
class Parser:
    def __init__(self, toks):
        self.toks=toks; self.i=0
    def peek(self, k=0):
        return self.toks[min(self.i+k, len(self.toks)-1)]
    def next(self):
        t=self.toks[self.i]; self.i+=1; return t
    def at_punct(self, v):
        t=self.peek(); return t.kind=="punct" and t.value==v
    def eat_punct(self, v):
        if self.at_punct(v): self.next(); return True
        return False
    def expect_punct(self, v):
        if not self.eat_punct(v):
            t=self.peek(); raise JSError(f"expecting '{v}'", "SyntaxError")
    def at_name(self, v=None):
        t=self.peek(); return t.kind=="name" and (v is None or t.value==v)
    def eat_name(self, v=None):
        if self.at_name(v): return self.next()
        return None

    def parse_program(self):
        stmts=[]
        while self.peek().kind!="eof":
            if self.eat_punct(";"): continue
            stmts.append(self.parse_statement())
        return stmts
    def parse_statement(self):
        if self.at_name("import"):
            # skip import statement up to semicolon or newline-ish: consume tokens balancing braces until ;
            depth=0
            while self.peek().kind!="eof":
                t=self.next()
                if t.kind=="punct" and t.value in ("{","(","["): depth+=1
                if t.kind=="punct" and t.value in ("}",")","]"): depth-=1
                if depth<=0 and t.kind=="punct" and t.value==";": break
                # side-effect imports end at string then optional ;
                if depth<=0 and t.kind=="string":
                    self.eat_punct(";"); break
            return ("noop",)
        if self.at_name("export"):
            self.next()
            if self.eat_name("default"):
                e=self.parse_expr()
                self.eat_punct(";")
                return ("export_default", e)
            # export const/function/{}
            if self.at_punct("{"):
                # skip export list, may have from
                self.skip_balanced()
                while self.peek().kind!="eof" and not self.at_punct(";"):
                    self.next()
                self.eat_punct(";"); return ("noop",)
            # fallthrough to declaration as statement value ignored
            st=self.parse_statement(); return st
        if self.at_name() and self.peek().value in ("const","let","var"):
            self.next(); decls=[]
            while True:
                # destructuring?
                if self.at_punct("{") or self.at_punct("["):
                    pattern_src=self.skip_balanced_raw()
                    self.expect_punct("=")
                    e=self.parse_expr(); decls.append((("pattern",pattern_src), e))
                else:
                    name=self.next().value
                    init=None
                    if self.eat_punct("="): init=self.parse_expr()
                    decls.append((name, init))
                if not self.eat_punct(","): break
            self.eat_punct(";")
            return ("vardecl", decls)
        if self.at_name("function"):
            self.next(); name=self.next().value if self.peek().kind=="name" else None
            params=self.parse_params()
            body=self.parse_block()
            return ("funcdecl", name, params, body)
        if self.at_name("return"):
            self.next()
            if self.at_punct(";") or self.at_punct("}"):
                self.eat_punct(";"); return ("return", None)
            e=self.parse_expr(); self.eat_punct(";"); return ("return", e)
        if self.at_punct("{"):
            return ("block", self.parse_block())
        # expression statement / assignment
        e=self.parse_expr()
        self.eat_punct(";")
        return ("expr", e)
    def skip_balanced(self):
        opening=self.next()
        pairs={"(":")","{":"}","[":"]"}
        close=pairs.get(opening.value,")")
        depth=1
        while depth>0 and self.peek().kind!="eof":
            t=self.next()
            if t.kind=="punct" and t.value==opening.value: depth+=1
            elif t.kind=="punct" and t.value==close: depth-=1
    def skip_balanced_raw(self):
        start=self.i; self.skip_balanced(); return self.toks[start:self.i]
    def parse_block(self):
        self.expect_punct("{"); stmts=[]
        while not self.at_punct("}"):
            if self.peek().kind=="eof": raise JSError("Unexpected EOF", "SyntaxError")
            if self.eat_punct(";"): continue
            stmts.append(self.parse_statement())
        self.expect_punct("}")
        return stmts
    def parse_params(self):
        self.expect_punct("("); params=[]
        while not self.at_punct(")"):
            if self.at_punct("..."): self.next()
            if self.peek().kind=="name": params.append(self.next().value)
            elif self.at_punct("{") or self.at_punct("["): self.skip_balanced(); params.append(f"_p{len(params)}")
            else: self.next()
            if self.eat_punct("="):
                self.parse_expr()  # default ignored
            if not self.eat_punct(","): break
        self.expect_punct(")")
        return params
    # expressions
    def parse_expr(self):
        return self.parse_assign()
    def parse_assign(self):
        # arrow detection: identifier =>
        if self.peek().kind=="name" and self.peek(1).kind=="punct" and self.peek(1).value=="=>":
            name=self.next().value; self.next()
            return self.parse_arrow_body([name])
        if self.at_punct("("):
            save=self.i
            try:
                params=self.parse_params()
                if self.at_punct("=>"):
                    self.next(); return self.parse_arrow_body(params)
                else:
                    raise JSError("not arrow","SyntaxError")
            except Exception:
                self.i=save
        left=self.parse_ternary()
        if self.at_punct("=") or self.at_punct("+=") or self.at_punct("-="):
            op=self.next().value; right=self.parse_assign()
            return ("assign", op, left, right)
        return left
    def parse_arrow_body(self, params):
        if self.at_punct("{"):
            body=self.parse_block(); return ("arrow", params, body, True)
        body=self.parse_assign(); return ("arrow", params, body, False)
    def parse_ternary(self):
        e=self.parse_binary(0)
        if self.eat_punct("?"):
            a=self.parse_assign(); self.expect_punct(":"); b=self.parse_assign()
            return ("ternary", e, a, b)
        return e
    BIN_LEVELS=[["||","??"],["&&"],["|"],["^"],["&"],["==","!=","===","!=="],["<",">","<=",">=", "in","instanceof"],["<<",">>"],["+","-"],["*","/","%"]]
    def parse_binary(self, level):
        if level>=len(self.BIN_LEVELS):
            return self.parse_unary()
        left=self.parse_binary(level+1)
        while True:
            t=self.peek()
            op=None
            if t.kind=="punct" and t.value in self.BIN_LEVELS[level]: op=t.value
            elif t.kind=="name" and t.value in self.BIN_LEVELS[level]: op=t.value
            if not op: break
            self.next(); right=self.parse_binary(level+1)
            left=("binary", op, left, right)
        return left
    def parse_unary(self):
        t=self.peek()
        if t.kind=="punct" and t.value in ("!","-","+","~"):
            self.next(); return ("unary", t.value, self.parse_unary())
        if t.kind=="name" and t.value in ("typeof","void","delete","await"):
            self.next(); return ("unary", t.value, self.parse_unary())
        if t.kind=="name" and t.value=="new":
            self.next(); e=self.parse_postfix(); return ("new", e)
        return self.parse_postfix()
    def parse_postfix(self):
        e=self.parse_primary()
        while True:
            if self.at_punct(".") or self.at_punct("?."):
                self.next(); prop=self.next().value if self.peek().kind in ("name","number") else ""
                # Actually next consumed? above peek check flawed - redo: we already moved? Let's implement carefully:
                # The line above: after dot, self.next() in conditional expression evaluation order may be wrong.
                e=("member", e, prop)
                continue
            if self.at_punct("["):
                self.next(); idx=self.parse_expr(); self.expect_punct("]"); e=("index", e, idx); continue
            if self.at_punct("("):
                self.next(); args=[]
                while not self.at_punct(")"):
                    if self.at_punct("..."): self.next(); args.append(("spread", self.parse_assign()))
                    else: args.append(self.parse_assign())
                    if not self.eat_punct(","): break
                self.expect_punct(")")
                e=("call", e, args); continue
            if self.peek().kind=="punct" and self.peek().value in ("++","--"):
                self.next(); continue
            break
        return e
    def parse_primary(self):
        t=self.peek()
        if t.kind=="number": self.next(); return ("lit", t.value)
        if t.kind=="string": self.next(); return ("lit", t.value)
        if t.kind=="regex": self.next(); return ("regex", t.value, t.flags)
        if t.kind=="template": self.next(); return ("template", t.value)
        if t.kind=="name":
            if t.value=="function":
                self.next()
                if self.peek().kind=="name": self.next()
                params=self.parse_params(); body=self.parse_block(); return ("arrow", params, body, True)
            if t.value in ("true","false"): self.next(); return ("lit", t.value=="true")
            if t.value=="null": self.next(); return ("lit", None)
            if t.value=="undefined": self.next(); return ("lit", None)
            self.next(); return ("name", t.value)
        if self.at_punct("("):
            self.next(); e=self.parse_expr()
            # comma sequence
            while self.eat_punct(","): e=self.parse_expr()
            self.expect_punct(")"); return e
        if self.at_punct("["):
            self.next(); elems=[]
            while not self.at_punct("]"):
                if self.eat_punct(","): elems.append(("lit",None)); continue
                if self.at_punct("..."): self.next(); elems.append(("spread", self.parse_assign()))
                else: elems.append(self.parse_assign())
                if not self.eat_punct(","): break
            self.expect_punct("]"); return ("array", elems)
        if self.at_punct("{"):
            self.next(); pairs=[]
            while not self.at_punct("}"):
                if self.at_punct("..."):
                    self.next(); pairs.append(("spread", self.parse_assign()))
                else:
                    kt=self.peek()
                    if kt.kind in ("string","number"): self.next(); key=str(kt.value)
                    elif kt.kind=="name":
                        # method shorthand?
                        key=kt.value; self.next()
                        if self.at_punct("("):
                            params=self.parse_params(); body=self.parse_block(); pairs.append((key, ("arrow", params, body, True))); 
                            if not self.eat_punct(","): 
                                if not self.at_punct("}"): pass
                            continue
                    else: self.next(); key=str(kt.value)
                    if self.eat_punct(":"):
                        val=self.parse_assign(); pairs.append((key, val))
                    else:
                        pairs.append((key, ("name", key)))
                if not self.eat_punct(","): break
                if self.at_punct("}"): break
            self.expect_punct("}"); return ("object", pairs)
        raise JSError(f"Unexpected token '{t.value}'", "SyntaxError")

# ---------------- evaluation ----------------
def normalize(v):
    if isinstance(v, str):
        return {"type":"STRING","value":v}
    if isinstance(v, RegexVal):
        d={"type":"PATTERN","value":v.value}
        if v.flags: d["flags"]=v.flags
        return d
    if isinstance(v, dict) and "type" in v:
        return v
    if isinstance(v, GrammarResult):
        return v
    raise JSError(f"Invalid rule: {v}", "TypeError")

def check_multi(args, name):
    # args from JS calls are already list; builtins receive *args, multi check handled by each caller signature
    pass

def make_builtins():
    def _alias(rule, value=None):
        result={"type":"ALIAS","content":normalize(rule),"named":False,"value":None}
        if isinstance(value, str):
            result["named"]=False; result["value"]=value; return result
        if isinstance(value, dict) and value.get("type")=="SYMBOL":
            result["named"]=True; result["value"]=value["name"]; return result
        raise JSError(f"Invalid alias value {value}", "Error")
    def _blank():
        return {"type":"BLANK"}
    def _field(name, rule=None):
        if rule is None: raise JSError("Missing field rule")
        return {"type":"FIELD","name":name,"content":normalize(rule)}
    def _choice(*elements):
        return {"type":"CHOICE","members":[normalize(e) for e in elements]}
    def _optional(value=None):
        return _choice(value, _blank())
    def make_prec(kind):
        def f(*args):
            if len(args)==1:
                number=0; rule=args[0]
                if kind!="PREC": pass
            elif len(args)>=2:
                number, rule=args[0], args[1]
            else:
                raise JSError("Missing precedence value")
            if number is None: raise JSError("Missing precedence value")
            return {"type":kind,"value":number,"content":normalize(rule)}
        return f
    def _prec(*args):
        if len(args)<2: raise JSError("Missing precedence value")
        return {"type":"PREC","value":args[0],"content":normalize(args[1])}
    prec_obj=Builtin(_prec); prec_obj.props={"left":Builtin(make_prec("PREC_LEFT")),"right":Builtin(make_prec("PREC_RIGHT")),"dynamic":Builtin(make_prec("PREC_DYNAMIC"))}
    def _repeat(rule=None):
        if rule is None: raise JSError("Missing rule")
        return {"type":"REPEAT","content":normalize(rule)}
    def _repeat1(rule=None):
        if rule is None: raise JSError("Missing rule")
        return {"type":"REPEAT1","content":normalize(rule)}
    def _seq(*elements):
        return {"type":"SEQ","members":[normalize(e) for e in elements]}
    def _token(value=None):
        return {"type":"TOKEN","content":normalize(value)}
    token_obj=Builtin(_token); token_obj.props={"immediate":Builtin(lambda v=None: {"type":"IMMEDIATE_TOKEN","content":normalize(v)})}
    def _reserved(wordset, rule=None):
        if not isinstance(wordset,str): raise JSError("Invalid reserved word set name: "+str(wordset))
        return {"type":"RESERVED","content":normalize(rule),"context_name":wordset}
    def _sym(name):
        return sym_expr(name)
    def _grammar(*args):
        return grammar_impl(*args)
    builtins={
        "alias":Builtin(_alias), "blank":Builtin(_blank), "field":Builtin(_field), "choice":Builtin(_choice),
        "optional":Builtin(_optional), "prec":prec_obj, "repeat":Builtin(_repeat), "repeat1":Builtin(_repeat1),
        "seq":Builtin(_seq), "token":token_obj, "reserved":Builtin(_reserved), "sym":Builtin(_sym), "grammar":Builtin(_grammar),
        "RegExp":Builtin(lambda pat="", flags="": RegexVal(str(pat), str(flags) if flags else "")),
    }
    return builtins

def grammar_impl(*args):
    if len(args)==1:
        base=None; options=args[0]
    elif len(args)>=2:
        base=args[0]; options=args[1]
    else:
        raise JSError("grammar requires arguments")
    if isinstance(base, GrammarResult):
        base_grammar=base.grammar
    elif isinstance(base, dict):
        base_grammar=base.get("grammar", base)
    else:
        base_grammar=None
    if not isinstance(options, dict):
        raise JSError("Grammar options must be an object")
    name=options.get("name", (base_grammar or {}).get("name"))
    if name is not None:
        if not isinstance(name,str) or not re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', name or ""):
            raise JSError("Grammar's 'name' property must not start with a digit and cannot contain non-word characters.", "Error")
    rules_raw=options.get("rules", (base_grammar or {}).get("rules", {}))
    if not isinstance(rules_raw, dict):
        raise JSError("Grammar's 'rules' property must be an object.")
    if len(rules_raw)==0:
        raise JSError("Grammar must have at least one rule.", "Error")
    rule_names=set(rules_raw.keys())
    # include inherited rule names?
    if base_grammar:
        rule_names |= set((base_grammar.get("rules") or {}).keys())
    builder=RuleBuilder(rule_names)
    any_builder=AnyBuilder()
    def call_opt(v):
        if isinstance(v, (Closure, Builtin)):
            # try calling with builder, builder, [] - closures accept fewer args in our Closure (pads None)
            return v(builder, any_builder, [])
        return v
    rules={}
    base_rules=(base_grammar or {}).get("rules", {}) if base_grammar else {}
    for k in base_rules:
        if k not in rules_raw:
            rules[k]=base_rules[k]
    for key, v in rules_raw.items():
        if isinstance(v, (Closure, Builtin)):
            val=v(builder, any_builder)
        else:
            val=v
        rules[key]=normalize(val)
    # extras
    if "extras" in options:
        ev=call_opt(options["extras"])
        extras=[normalize(e) for e in ev] if isinstance(ev, list) else [normalize(ev)]
    elif base_grammar and "extras" in base_grammar:
        extras=base_grammar["extras"]
    else:
        extras=[{"type":"PATTERN","value":r"\s"}]
    def list_of_symbols(opt_name, base_val=[]):
        if opt_name in options:
            ev=call_opt(options[opt_name])
            out=[]
            for s in ev:
                if isinstance(s, dict) and s.get("type")=="SYMBOL": out.append(s["name"])
                else: raise JSError(f"Invalid symbol in '{opt_name}'")
            return out
        return list(base_val)
    conflicts=[]
    if "conflicts" in options:
        ev=call_opt(options["conflicts"])
        for group in ev:
            conflicts.append([s["name"] if isinstance(s,dict) else str(s) for s in group])
    elif base_grammar: conflicts=base_grammar.get("conflicts",[])
    precedences=[]
    if "precedences" in options:
        ev=call_opt(options["precedences"])
        for group in ev:
            precedences.append([normalize(s) for s in group])
    elif base_grammar: precedences=base_grammar.get("precedences",[])
    externals=[]
    if "externals" in options:
        ev=call_opt(options["externals"])
        externals=[normalize(e) for e in ev]
    elif base_grammar: externals=base_grammar.get("externals",[])
    inline=list_of_symbols("inline", (base_grammar or {}).get("inline",[]))
    supertypes=list_of_symbols("supertypes", (base_grammar or {}).get("supertypes",[]))
    word=None
    if "word" in options:
        ev=call_opt(options["word"])
        if isinstance(ev, dict) and ev.get("type")=="SYMBOL": word=ev["name"]
    elif base_grammar: word=base_grammar.get("word")
    reserved={}
    if "reserved" in options:
        robj=options["reserved"]
        if isinstance(robj, dict):
            for k, v in robj.items():
                ev=v(builder, any_builder, []) if isinstance(v,(Closure,Builtin)) else v
                reserved[k]=[normalize(e) for e in ev]
    elif base_grammar: reserved=base_grammar.get("reserved",{})
    g={}
    g["name"]=name
    if word: g["word"]=word
    g["rules"]=rules
    g["extras"]=extras
    g["conflicts"]=conflicts
    g["precedences"]=precedences
    g["externals"]=externals
    g["inline"]=inline
    g["supertypes"]=supertypes
    g["reserved"]=reserved
    return GrammarResult(g)

def eval_block(stmts, env):
    for st in stmts:
        if st[0]=="return":
            raise ReturnSignal(eval_expr(st[1], env) if st[1] is not None else None)
        exec_stmt(st, env)
    return None

class ReturnSignal(Exception):
    def __init__(self, value): self.value=value

def exec_stmt(st, env):
    kind=st[0]
    if kind=="noop": return
    if kind=="export_default":
        env.set("__export_default__", eval_expr(st[1], env)); return
    if kind=="vardecl":
        for name, init in st[1]:
            val=eval_expr(init, env) if init is not None else None
            if isinstance(name, tuple):
                # destructuring: if val dict, assign keys? skip - store whole under placeholder
                if isinstance(val, dict):
                    # try extract names from tokens
                    toks=name[1]
                    for t in toks:
                        if t.kind=="name" and t.value not in ("const",):
                            env.set_local(t.value, val.get(t.value) if isinstance(val, dict) else None)
                continue
            env.set_local(name, val)
        return
    if kind=="funcdecl":
        if st[1]: env.set_local(st[1], Closure(st[2], st[3], env, True))
        return
    if kind=="block":
        try: eval_block(st[1], Env(parent=env))
        except ReturnSignal as r: raise r
        return
    if kind=="expr":
        eval_expr(st[1], env); return
    if kind=="return":
        raise ReturnSignal(eval_expr(st[1], env) if st[1] is not None else None)

def get_member(obj, prop):
    if isinstance(obj, RuleBuilder) or isinstance(obj, AnyBuilder):
        return obj.get(prop)
    if isinstance(obj, Builtin):
        if prop in obj.props: return obj.props[prop]
        return None
    if isinstance(obj, GrammarResult):
        if prop=="grammar": return obj.grammar
        return None
    if isinstance(obj, dict):
        return obj.get(prop)
    if isinstance(obj, str):
        if prop=="length": return len(obj)
        return None
    if isinstance(obj, list):
        if prop=="length": return len(obj)
        return None
    if obj is None:
        raise JSError(f"Cannot read properties of undefined (reading '{prop}')", "TypeError")
    return None

def call_value(fn, args):
    if isinstance(fn, Closure):
        try:
            return fn(*args)
        except ReturnSignal as r:
            return r.value
    if isinstance(fn, Builtin):
        return fn(*args)
    if callable(fn):
