            # productions: content  | content aux (right recursive)
            # For repeat, also single content handled by content+aux(empty) but add direct for simpler building
            if rhs_content:
                self._add_prod(aux, rhs_content, {"kind":"repeat"})
                self._add_prod(aux, rhs_content+[('N',aux)], {"kind":"repeat"})
            return ('N', aux)
        if t=="FIELD":
            aux=self._new_aux("field"); self._expand(aux, expr.get("content",{}), {"kind":"field","name":expr.get("name")}); return ('N', aux)
        if t=="ALIAS":
            aux=self._new_aux("alias"); self._expand(aux, expr.get("content",{}), {"kind":"alias","value":expr.get("value"),"named":expr.get("named",False)}); return ('N', aux)
        if t in ("PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC","RESERVED","CHOICE","SEQ"):
            aux=self._new_aux("aux"); self._expand(aux, expr, {"kind":"aux"}); return ('N', aux)
        # fallback
        aux=self._new_aux("aux"); self._expand(aux, expr, {"kind":"aux"}); return ('N', aux)
    def _build_extra_specs(self):
        specs=[]
        for expr in self.extras_exprs:
            if not isinstance(expr,dict): continue
            t=expr.get("type")
            if t=="PATTERN":
                specs.append((compile_regex(expr.get("value",""), expr.get("flags","")), None, False))
            elif t=="STRING":
                specs.append((compile_regex(re.escape(expr.get("value",""))), expr.get("value",""), False))
            elif t=="SYMBOL":
                nm=expr.get("name")
                if nm in self.rules and self.is_token_rule(nm):
                    term=self.term_for_named_token(nm)
                    specs.append((term.regex, (nm if term.named else term.node_type), term.named))
                elif nm in self.rules:
                    # non-token extra rule: compile as token if possible
                    term=self.make_term_for_token_expr(self.rules[nm], node_type=nm, named=not nm.startswith("_"))
                    specs.append((term.regex, nm, not nm.startswith("_")))
                else:
                    specs.append((compile_regex(r".*"), nm, True))
            elif t in ("TOKEN","IMMEDIATE_TOKEN"):
                term=self.make_term_for_token_expr(expr)
                specs.append((term.regex, term.node_type if term.named else None, term.named))
            else:
                term=self.make_term_for_token_expr(expr)
                if term.regex: specs.append((term.regex, None, False))
        return specs

class EarleyParser:
    def __init__(self, grammar_dict, text):
        self.cg=CompiledGrammar(grammar_dict)
        self.text=text
        self.n=len(text)
        self.token_cache={}
        self.has_error=False
    # extras consumption: returns list of (extras_nodes, endpos) - greedy one option
    def consume_extras(self, pos):
        extras=[]; cur=pos
        while cur<self.n:
            matched=False
            for regex, node_type, named in self.cg.extra_specs:
                if regex is None: continue
                m=regex.match(self.text, cur)
                if m and m.end()>cur:
                    if node_type is not None:
                        extras.append(Node(node_type, named, cur, m.end(), extra=True, text_src=self.text))
                    cur=m.end(); matched=True; break
                elif m and m.end()==cur:
                    continue
            if not matched: break
        return extras, cur
    def scan_term(self, term, pos):
        key=(term.key, pos)
        if key in self.token_cache: return self.token_cache[key]
        results=[]
        if term.immediate:
            end=term.match(self.text, pos)
            if end is not None:
                node=Node(term.node_type, term.named, pos, end, text_src=self.text)
                node.leading=[]
                results.append((node,end))
        else:
            extras, cur=self.consume_extras(pos)
            end=term.match(self.text, cur) if cur<=self.n else None
            if end is not None:
                node=Node(term.node_type, term.named, cur, end, text_src=self.text)
                node.leading=[e.clone() for e in extras]
                results.append((node,end))
        self.token_cache[key]=results
        return results
    def parse(self):
        cg=self.cg
        if cg.start_rule is None:
            return None
        # wrapper element for start
        start_expr={"type":"SYMBOL","name":cg.start_rule}
        # Use internal run
        wrapper_name="__root__"
        # create wrapper prod temporarily in cg
        # Build element using cg._element but it may add aux prods; do before run and reindex
        el=cg._element(start_expr)
        wrapper_prod=Prod(wrapper_name, [el], {"kind":"root"})
        cg.prods.append(wrapper_prod)
        cg.prods_by_lhs={} 
        for idx,p in enumerate(cg.prods): cg.prods_by_lhs.setdefault(p.lhs,[]).append(idx)
        completed, charts = self._run(wrapper_name, 0)
        candidates=[]
        for (lhs,start,end), families in completed.items():
            if lhs==wrapper_name and start==0:
                extras, final=self.consume_extras(end)
                if final==self.n:
                    candidates.append((end, extras))
                elif end==self.n:
                    candidates.append((end, []))
        if candidates:
            # prefer longest end (all =?) build
            candidates.sort(key=lambda x: x[0])
            end, trailing = candidates[-1]
            res=self._build((wrapper_name,0,end), completed, set())
            if res and res.nodes:
                root=res.nodes[0]
                # root may be token or node; ensure children list
                # Insert leading
                leading=res.leading  # wrapper leading = root node's leading? root node itself stored leading inside? Wrapper BuildResult leading is child leading
                # res.nodes[0] may already be root; insert leading extras that are before root
                # Wrapper assembly: root wrapper is transparent, its first child leading becomes wrapper leading, not inserted. res.leading is that.
                children_prefix=[e.clone() for e in leading] if leading else []
                # If root is same as first token node, leading should become children prefix (if extras named)
                if children_prefix:
                    root.children = children_prefix + root.children
                    root.start = children_prefix[0].start
                if trailing:
                    root.children = root.children + [e.clone() for e in trailing]
                root.start = 0 if (self.text[:root.start].strip()=="" or children_prefix or root.start!=0) and False else root.start
                # Tree-sitter root spans whole file when trailing whitespace/comments consumed: set start to min(root.start, first token?) Keep original first node start except: if leading whitespace only, original root starts at 0.
                # Determine: if text before root.start consists only of extras (whitespace/comments already in children) set to 0 if file starts there? Simpler: if root is start_rule node, set start=0 when all preceding text is whitespace or extras consumed (it is, because parse started at 0 with extras). Actually extras before first token were stored as leading and inserted only if named; whitespace preceding still part of root span in tree-sitter (root starts at 0,0 generally).
                root.start = 0
                root.end = self.n
                # If root is a token leaf and had children added, fine
                return root
        # failure fallback
        self.has_error=True
        return self._fallback_parse(completed if 'completed' in locals() else {})
    def _run(self, start_lhs, origin):
        cg=self.cg; n=self.n
        # charts: list of dicts itemkey-> [prod,dot,origin, derivations(list), processed_count]
        charts=[]
        def ensure_chart(i):
            while len(charts)<=i: charts.append({})
        ensure_chart(origin)
        completed={}  # (lhs,start,end)-> set families
        completed_list={}
        work=[]  # (chart_index, itemkey)
        def add_item(chart_idx, prod_idx, dot, orig, derivation):
            ensure_chart(chart_idx)
            key=(prod_idx,dot,orig)
            chart=charts[chart_idx]
            if key not in chart:
                chart[key]=[prod_idx,dot,orig,[derivation],0]
                work.append((chart_idx,key))
            else:
                if derivation not in chart[key][3]:
                    chart[key][3].append(derivation)
                    work.append((chart_idx,key))
        # initial items
        for prod_idx in cg.prods_by_lhs.get(start_lhs,[]):
            add_item(origin, prod_idx, 0, origin, ())
        idx=0
        # Worklist may grow across charts; process in roughly chart order: we will loop scanning work list but ensure lower chart indices processed first by sorting periodically?
        # Simple index pointer; items added to future charts appended, items added to current/past charts also appended at end and will be processed.
        while idx < len(work):
            chart_idx, key = work[idx]; idx+=1
            ensure_chart(chart_idx)
            chart=charts[chart_idx]
            if key not in chart: continue
            item=chart[key]
            prod_idx,dot,orig,derivations,processed = item
            # process all unprocessed derivations
            while item[4] < len(item[3]):
                derivation=item[3][item[4]]; item[4]+=1
                prod=cg.prods[prod_idx]
                if dot < len(prod.rhs):
                    elem_kind, elem = prod.rhs[dot]
                    if elem_kind=='N':
                        # predict
                        for pidx in cg.prods_by_lhs.get(elem,[]):
                            add_item(chart_idx, pidx, 0, chart_idx, ())
                        # epsilon / already completed at same pos
                        fam_key=(elem, chart_idx, chart_idx)
                        if fam_key in completed:
                            for fam in list(completed[fam_key]):
                                add_item(chart_idx, prod_idx, dot+1, orig, derivation+(('N',elem,chart_idx,chart_idx),))
                        # also completed spanning to future already registered? (possible if chart_idx revisit) check any completed (elem,chart_idx,end)
                        for (lhs,s,e), fams in list(completed.items()):
                            if lhs==elem and s==chart_idx and e!=chart_idx:
                                for fam in list(fams):
                                    add_item(e, prod_idx, dot+1, orig, derivation+(('N',elem,s,e),))
                    else:
                        term=elem
                        for token_node, endpos in self.scan_term(term, chart_idx):
                            # store token node in a ref by identity: encode as ('T', token_node) - token node object hashable by id? Use object directly in tuple (Node defines no eq, hash by id default)
                            add_item(endpos, prod_idx, dot+1, orig, derivation+(('T', token_node),))
                else:
                    # complete
                    fam_key=(prod.lhs, orig, chart_idx)
                    fam=(prod_idx, derivation)
                    if fam_key not in completed:
                        completed[fam_key]=set(); completed_list[fam_key]=[]
                    if fam not in completed[fam_key]:
                        completed[fam_key].add(fam); completed_list[fam_key].append(fam)
                        # advance waiting items in origin chart
                        if orig < len(charts):
                            waiting=list(charts[orig].items())
                            for wkey, witem in waiting:
                                wprod=cg.prods[witem[0]]
                                if witem[1] < len(wprod.rhs):
                                    ek, ev = wprod.rhs[witem[1]]
                                    if ek=='N' and ev==prod.lhs:
                                        for wderiv in list(witem[3]):
                                            add_item(chart_idx, witem[0], witem[1]+1, witem[2], wderiv+(('N',prod.lhs,orig,chart_idx),))
            # loop derivations
        return completed_list, charts
    def _build(self, key, completed, stack):
        if key in stack: return None
        lhs,start,end=key
        families=completed.get(key,[])
        if not families: return None
        stack=set(stack); stack.add(key)
        best=None
        for prod_idx, derivation in families:
            prod=self.cg.prods[prod_idx]
            child_results=[]
            ok=True
            for ref in derivation:
                if ref[0]=='T':
                    token=ref[1]
                    cloned=token.clone()
                    res=BuildResult([cloned], leading=[e.clone() for e in token.leading], score=1)
                    child_results.append(res)
                else:
                    _, clhs, cs, ce = ref
                    sub=self._build((clhs,cs,ce), completed, stack)
                    if sub is None: ok=False; break
                    child_results.append(sub)
            if not ok: continue
            res=self._assemble(prod, child_results, start, end)
            if res is None: continue
            # scoring
            score=res.score + sum(cr.score for cr in child_results)
            if isinstance(prod.prec_value,(int,float)): score += prod.prec_value*0.1
            # associativity bonuses
            if prod.prec_kind in ("left","right") and derivation:
                refs=[r for r in derivation]
                if prod.prec_kind=="left" and refs:
                    first=refs[0]
                    if first[0]=='N':
                        # if first child's built node type equals lhs or its span large
                        if child_results and child_results[0].nodes and child_results[0].nodes[0].type==lhs:
                            score += (first[3]-first[2]) * 0.01
                if prod.prec_kind=="right" and refs:
                    last=refs[-1]
                    if last[0]=='N':
                        if child_results and child_results[-1].nodes and child_results[-1].nodes[0].type==lhs:
                            score += (last[3]-last[2]) * 0.01
            res.score=score
            if best is None or score>best.score:
                best=res
        return best
    def _assemble(self, prod, child_results, start, end):
        builder=prod.builder; kind=builder.get("kind")
        seq_nodes=[]; leading=[]
        for i, cr in enumerate(child_results):
            if cr.leading:
                if i==0:
                    leading.extend([e.clone() for e in cr.leading])
                else:
                    seq_nodes.extend([e.clone() for e in cr.leading])
            seq_nodes.extend(cr.nodes)
        if kind in ("aux","repeat","root"):
            return BuildResult(seq_nodes, leading=leading)
        if kind=="field":
            for node in seq_nodes: node.field=builder.get("name")
            return BuildResult(seq_nodes, leading=leading)
        if kind=="alias":
            if seq_nodes:
                main=seq_nodes[0]; main.type=builder.get("value"); main.named=bool(builder.get("named"))
            return BuildResult(seq_nodes, leading=leading)
        if kind=="rule":
            name=builder.get("name")
            if name.startswith("_") or name in self.cg.supertypes or name in self.cg.inline:
                return BuildResult(seq_nodes, leading=leading)
            if seq_nodes:
                s=seq_nodes[0].start; e=seq_nodes[-1].end
            else:
                s=start; e=end
            node=Node(name, True, s, e, children=seq_nodes, text_src=self.text)
            return BuildResult([node], leading=leading)
        return BuildResult(seq_nodes, leading=leading)
    def try_parse_symbol(self, element, pos):
        # element is ('N',name) or ('T',term)
        if element[0]=='T':
            res=self.scan_term(element[1], pos)
            if res:
                node,end=res[0]; return ([node.clone()], end, [e.clone() for e in node.leading])
            return None
        name=element[1]
        if name in self.cg.rules and self.cg.is_token_rule(name):
            res=self.scan_term(self.cg.term_for_named_token(name), pos)
            if res:
                node,end=res[0]; return ([node.clone()], end, [e.clone() for e in node.leading])
            return None
        wrapper="__sym__"
        # Add wrapper prod each time? Creating new wrapper per call may accumulate; create unique
        wrapper=f"__sym{abs(hash((name,pos)))%100000}__"
        el=('N',name)
        self.cg.prods.append(Prod(wrapper,[el],{"kind":"root"}))
        self.cg.prods_by_lhs={}
        for idx,p in enumerate(self.cg.prods): self.cg.prods_by_lhs.setdefault(p.lhs,[]).append(idx)
        completed,_=self._run(wrapper,pos)
        candidates=[]
        for (lhs,s,e),fams in completed.items():
            if lhs==wrapper and s==pos and e>pos:
                candidates.append(e)
        if not candidates: return None
        candidates.sort()
        # prefer longest? For fallback tiling, smallest end that still? Use longest as subparse may consume following units as part of e.g. binary - that's fine. But for expression starting at a, longest is whole binary, good.
        # However to allow segmentation, choose longest candidate
        e=candidates[-1]
        res=self._build((wrapper,pos,e), completed, set())
        if res and res.nodes:
            return (res.nodes, e, res.leading)
        return None
    def _fallback_parse(self, completed):
        cg=self.cg
        root_name=cg.start_rule
        children=[]
        pos=0
        # Determine unit elements from root expr
        units=self._root_units()
        if not units:
            units=[('N',root_name)] if root_name not in (None,) else []
        # helper to try units at p
        def try_units(p):
            best=None
            for el in units:
                r=self.try_parse_symbol(el,p)
                if r:
                    nodes,end,leading=r
                    if end>p and (best is None or end>best[1]):
                        best=(nodes,end,leading,el)
            return best
        # If a whole root parse exists for a prefix, we could use segmentation via units anyway
        iterations=0
        while pos<self.n and iterations<10000:
            iterations+=1
            extras, after_extras=self.consume_extras(pos)
            # extras named nodes add (except before error we still add)
            named_extras=[e for e in extras]
            # try parse at pos (scan handles extras)
            attempt=try_units(pos)
            if attempt:
                nodes,end,leading,el = attempt
                # leading extras from first node
                for le in leading: children.append(le.clone())
                # If unit is root itself, splice its children
                if nodes and len(nodes)==1 and nodes[0].type==root_name and el==('N',root_name):
                    children.extend(nodes[0].children)
                else:
                    children.extend(nodes)
                pos=end
                continue
            # No parse: error chunk
            err_start=after_extras
            if err_start>=self.n: break
            # find next position where a unit parses, get its token start
            found=None; found_nodes_start=None
            q=err_start+1
            while q<=self.n:
                att=try_units(q)
                if att:
                    nodes,end,leading,el=att
                    # first real node start: if leading extras before token, token node is nodes[0] start
                    first_start=nodes[0].start if nodes else q
                    # if error chunk is only whitespace before this, don't create error
                    found=q; found_nodes_start=first_start; found_attempt=att; break
                q+=1
            err_end=found_nodes_start if found is not None else self.n
            if err_end<=err_start: err_end=min(self.n, err_start+1)
            inner=Node("ERROR", True, err_start, err_end, text_src=self.text)
            outer=Node("ERROR", True, err_start, err_end, children=[inner], text_src=self.text)
            # leading named extras before error (comments) add before error
            for le in named_extras: children.append(le.clone())
            children.append(outer)
            pos=err_end
            if found is None: break
        root=Node(root_name, True, 0, self.n, children=children, text_src=self.text)
        return root
    def _root_units(self):
        cg=self.cg
        if cg.start_rule not in cg.rules: return []
        expr=cg.rules[cg.start_rule]
        units=[]
        def unwrap(e):
            while isinstance(e,dict) and e.get("type") in ("PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC","RESERVED","TOKEN"):
                e=e.get("content",{})
            return e
        e=unwrap(expr)
        if not isinstance(e,dict): return []
        t=e.get("type")
        if t in ("REPEAT","REPEAT1"):
            el=cg._element(e.get("content",{}))
            if el: units.append(el)
            # update prod index because _element may add prods
            cg.prods_by_lhs={}
            for idx,p in enumerate(cg.prods): cg.prods_by_lhs.setdefault(p.lhs,[]).append(idx)
        elif t=="CHOICE":
            for m in e.get("members",[]):
                el=cg._element(m); 
                if el: units.append(el)
            cg.prods_by_lhs={}
            for idx,p in enumerate(cg.prods): cg.prods_by_lhs.setdefault(p.lhs,[]).append(idx)
        elif t=="SYMBOL":
            el=cg._element(e)
            if el: units.append(el)
        elif t=="SEQ":
            for m in e.get("members",[]):
                mm=unwrap(m)
                if isinstance(mm,dict) and mm.get("type") in ("REPEAT","REPEAT1"):
                    el=cg._element(mm.get("content",{}))
                    if el: units.append(el)
                elif isinstance(mm,dict) and mm.get("type")=="SYMBOL":
                    el=cg._element(mm)
                    if el: units.append(el)
            cg.prods_by_lhs={}
            for idx,p in enumerate(cg.prods): cg.prods_by_lhs.setdefault(p.lhs,[]).append(idx)
        return units
