import re, copy

class Node:
    __slots__=("type","named","start","end","children","field","extra","leading","text_src")
    def __init__(self, type, named, start, end, children=None, field=None, extra=False, text_src=""):
        self.type=type; self.named=named; self.start=start; self.end=end
        self.children=children or []; self.field=field; self.extra=extra; self.leading=[]; self.text_src=text_src
    @property
    def text(self):
        return self.text_src[self.start:self.end] if self.text_src else ""
    def clone(self):
        n=Node(self.type,self.named,self.start,self.end,[c.clone() for c in self.children],self.field,self.extra,self.text_src)
        n.leading=[c.clone() for c in self.leading]
        return n
    def all_nodes(self):
        yield self
        for c in self.children:
            yield from c.all_nodes()

def translate_pattern(pat):
    # basic \p translations
    pat = pat.replace(r"\p{L}", r"[^\W\d_]")
    pat = pat.replace(r"\p{Lu}", r"[A-Z]")
    pat = pat.replace(r"\p{Ll}", r"[a-z]")
    pat = pat.replace(r"\p{N}", r"\d")
    # JS \d etc compatible; \/ ok
    return pat

def compile_regex(pat, flags_str=""):
    flags=0
    if "i" in (flags_str or ""): flags|=re.I
    if "s" in (flags_str or ""): flags|=re.S
    if "m" in (flags_str or ""): flags|=re.M
    try:
        return re.compile(translate_pattern(pat), flags)
    except re.error:
        # try escaping unsupported constructs crudely
        try:
            return re.compile(translate_pattern(pat).replace(r"\z", r"\Z"), flags)
        except Exception:
            return re.compile(r"(?!)", flags)

class Term:
    __slots__=("key","node_type","named","regex","literal","immediate","prec","flags")
    def __init__(self, key, node_type, named, regex=None, literal=None, immediate=False, prec=0):
        self.key=key; self.node_type=node_type; self.named=named; self.regex=regex; self.literal=literal; self.immediate=immediate; self.prec=prec
    def match(self, text, pos):
        if self.literal is not None:
            if text.startswith(self.literal, pos): return pos+len(self.literal)
            return None
        if self.regex is not None:
            m=self.regex.match(text, pos)
            if m and m.end()>pos: return m.end()
            if m and m.end()==pos: return None
            return None
        return None

class Prod:
    __slots__=("lhs","rhs","builder","prec_kind","prec_value")
    def __init__(self,lhs,rhs,builder,prec_kind=None,prec_value=0):
        self.lhs=lhs; self.rhs=rhs; self.builder=builder; self.prec_kind=prec_kind; self.prec_value=prec_value

class BuildResult:
    __slots__=("nodes","leading","score")
    def __init__(self,nodes,leading=None,score=0):
        self.nodes=nodes; self.leading=leading or []; self.score=score

class CompiledGrammar:
    def __init__(self, grammar):
        self.grammar=grammar
        self.name=grammar.get("name","")
        self.rules=grammar.get("rules",{}) or {}
        self.start_rule=next(iter(self.rules), None)
        self.supertypes=set(grammar.get("supertypes",[]) or [])
        self.inline=set(grammar.get("inline",[]) or [])
        self.extras_exprs=grammar.get("extras",[{"type":"PATTERN","value":r"\s"}]) or []
        self.externals=grammar.get("externals",[]) or []
        self._token_rule_cache={}
        self.prods=[]
        self.prods_by_lhs={}
        self.aux_counter=0
        self.terms={}  # key->Term
        self.extra_specs=self._build_extra_specs()
        for name, expr in self.rules.items():
            if self.is_token_rule(name):
                continue
            self._expand(name, expr, {"kind":"rule","name":name})
        # index prods
        for idx,p in enumerate(self.prods):
            p._idx=idx if hasattr(p,'_idx') else None
            self.prods_by_lhs.setdefault(p.lhs,[]).append(idx)
    # ---------- token rule detection ----------
    def is_token_rule(self, name, visited=None):
        if name in self._token_rule_cache: return self._token_rule_cache[name]
        if name not in self.rules: return False
        if visited and name in visited: return False
        visited=set(visited or []); visited.add(name)
        expr=self.rules[name]
        res=self._is_token_expr(expr, inside_token=False, visited=visited)
        self._token_rule_cache[name]=res
        return res
    def _is_token_expr(self, expr, inside_token, visited):
        if not isinstance(expr,dict): return False
        t=expr.get("type")
        if t in ("STRING","PATTERN"): return True
        if t in ("TOKEN","IMMEDIATE_TOKEN"): return True
        if t in ("PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC","RESERVED"): return self._is_token_expr(expr.get("content",{}), inside_token, visited)
        if t=="SEQ": return all(self._is_token_expr(m, inside_token, visited) for m in expr.get("members",[]))
        if t=="CHOICE": return all(self._is_token_expr(m, inside_token, visited) for m in expr.get("members",[]))
        if t in ("REPEAT","REPEAT1"): return self._is_token_expr(expr.get("content",{}), inside_token, visited)
        if t=="SYMBOL":
            if inside_token:
                nm=expr.get("name")
                if nm in self.rules: return self.is_token_rule(nm, visited)
                return True
            return False
        if t=="BLANK": return True
        return False
    # ---------- regex building ----------
    def token_regex_str(self, expr, visited=None):
        if visited is None: visited=set()
        if not isinstance(expr,dict): return r"(?:)"
        t=expr.get("type")
        if t=="STRING": return re.escape(expr.get("value",""))
        if t=="PATTERN":
            pat=translate_pattern(expr.get("value",""))
            fl=expr.get("flags","") or ""
            pre=""
            if "i" in fl: pre+="i"
            if "s" in fl: pre+="s"
            if "m" in fl: pre+="m"
            if pre: return f"(?{pre}:{pat})"
            return f"(?:{pat})"
        if t in ("TOKEN","IMMEDIATE_TOKEN","PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC","RESERVED","FIELD","ALIAS"):
            return self.token_regex_str(expr.get("content",{}), visited)
        if t=="SEQ": return "".join(self.token_regex_str(m, visited) for m in expr.get("members",[]))
        if t=="CHOICE": return "(?:" + "|".join(self.token_regex_str(m, visited) for m in expr.get("members",[])) + ")"
        if t=="REPEAT": return f"(?:{self.token_regex_str(expr.get('content',{}), visited)})*"
        if t=="REPEAT1": return f"(?:{self.token_regex_str(expr.get('content',{}), visited)})+"
        if t=="BLANK": return r"(?:)"
        if t=="SYMBOL":
            nm=expr.get("name")
            if nm in visited: return r"(?:)"
            if nm in self.rules:
                visited2=set(visited); visited2.add(nm)
                return f"(?:{self.token_regex_str(self.rules[nm], visited2)})"
            return r"(?:.*?)"
        return r"(?:)"
    def _prec_value(self, expr):
        v=expr.get("value",0)
        return v if isinstance(v,(int,float)) else 0
    def make_term_for_token_expr(self, expr, node_type=None, named=None, immediate=False):
        # unwrap prec/token for prec value
        prec=0; imm=immediate; e=expr
        while isinstance(e,dict) and e.get("type") in ("PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC"):
            if isinstance(e.get("value"),(int,float)): prec=e["value"]
            e=e.get("content",{})
        if isinstance(e,dict) and e.get("type")=="IMMEDIATE_TOKEN": imm=True; e=e.get("content",{})
        if isinstance(e,dict) and e.get("type")=="TOKEN": e=e.get("content",{})
        # node type determination
        if node_type is None:
            if isinstance(e,dict) and e.get("type")=="STRING": node_type=e.get("value",""); named=False if named is None else named
            elif isinstance(e,dict) and e.get("type")=="SYMBOL":
                nm=e.get("name"); node_type=nm; named=(not nm.startswith("_")) if named is None else named
            elif isinstance(e,dict) and e.get("type")=="PATTERN": node_type=e.get("value",""); named=False if named is None else named
            else:
                # literal concatenation if seq of strings
                lit=self._literal_from_expr(e)
                if lit is not None: node_type=lit; named=False if named is None else named
                else: node_type=""; named=False if named is None else named
        key=("tok", id(expr), node_type, imm)
        # Use deterministic key based on regex string instead of id for caching? id ok per grammar lifetime but expr object reused; key uniqueness fine
        regex_str=self.token_regex_str(expr)
        key=("tok", regex_str, node_type, imm, prec)
        if key in self.terms: return self.terms[key]
        term=Term(key, node_type, bool(named), regex=compile_regex(regex_str), immediate=imm, prec=prec)
        self.terms[key]=term; return term
    def _literal_from_expr(self, expr):
        if not isinstance(expr,dict): return None
        t=expr.get("type")
        if t=="STRING": return expr.get("value","")
        if t=="SEQ":
            parts=[]
            for m in expr.get("members",[]):
                p=self._literal_from_expr(m)
                if p is None: return None
                parts.append(p)
            return "".join(parts)
        if t in ("TOKEN","IMMEDIATE_TOKEN","PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC"): return self._literal_from_expr(expr.get("content",{}))
        return None
    def term_for_named_token(self, name):
        key=("namedtok", name)
        if key in self.terms: return self.terms[key]
        expr=self.rules.get(name,{})
        named=not name.startswith("_")
        # if hidden token rule whose content is a string, anonymous token type is that string
        node_type=name
        if name.startswith("_"):
            lit=self._literal_from_expr(expr)
            if lit is not None: node_type=lit; named=False
        term=self.make_term_for_token_expr(expr, node_type=node_type, named=named)
        # make_term uses different key; also register named key mapping to same object
        self.terms[key]=term
        return term
    def make_string_term(self, value):
        key=("str", value)
        if key not in self.terms: self.terms[key]=Term(key, value, False, literal=value)
        return self.terms[key]
    def make_pattern_term(self, expr):
        key=("pat", expr.get("value",""), expr.get("flags",""))
        if key not in self.terms:
            regex=compile_regex(expr.get("value",""), expr.get("flags",""))
            self.terms[key]=Term(key, expr.get("value",""), False, regex=regex)
        return self.terms[key]
    # ---------- production building ----------
    def _new_aux(self, kind):
        self.aux_counter+=1; return f"__aux{self.aux_counter}_{kind}"
    def _add_prod(self, lhs, rhs, builder, prec_kind=None, prec_value=0):
        p=Prod(lhs, rhs, builder, prec_kind, prec_value); self.prods.append(p); return p
    def _expand(self, lhs, expr, builder, prec_kind=None, prec_value=0):
        if not isinstance(expr,dict):
            self._add_prod(lhs, [], builder); return
        t=expr.get("type")
        if t in ("PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC"):
            kind={"PREC":"prec","PREC_LEFT":"left","PREC_RIGHT":"right","PREC_DYNAMIC":"dynamic"}[t]
            val=expr.get("value",0)
            self._expand(lhs, expr.get("content",{}), builder, kind, val if isinstance(val,(int,float)) else 0); return
        if t=="RESERVED":
            self._expand(lhs, expr.get("content",{}), builder, prec_kind, prec_value); return
        if t=="CHOICE":
            for m in expr.get("members",[]):
                self._expand(lhs, m, builder, prec_kind, prec_value)
            return
        if t=="SEQ":
            rhs=[self._element(m) for m in expr.get("members",[])]
            self._add_prod(lhs, rhs, builder, prec_kind, prec_value); return
        if t=="BLANK":
            self._add_prod(lhs, [], builder, prec_kind, prec_value); return
        # single element
        el=self._element(expr, top_rule_builder=builder)
        if el is None:
            self._add_prod(lhs, [], builder, prec_kind, prec_value)
        elif isinstance(el, str) and el==lhs and builder.get("kind")!="rule":
            # avoid trivial self? still add
            self._add_prod(lhs, [('N',el)], builder, prec_kind, prec_value)
        elif isinstance(el, tuple):
            # if element is the aux etc, just prod with it; if element refers to same lhs nonterm, also
            self._add_prod(lhs, [el], builder, prec_kind, prec_value)
        else:
            self._add_prod(lhs, [], builder, prec_kind, prec_value)
    def _element(self, expr, top_rule_builder=None):
        if not isinstance(expr,dict): return None
        t=expr.get("type")
        if t=="SYMBOL":
            nm=expr.get("name")
            # external?
            if nm in self.rules and self.is_token_rule(nm):
                return ('T', self.term_for_named_token(nm))
            if nm in self.rules:
                return ('N', nm)
            # unknown symbol: treat as named terminal token
            key=("exttok",nm)
            if key not in self.terms: self.terms[key]=Term(key, nm, True, regex=compile_regex(r".+?"))
            return ('T', self.terms[key])
        if t=="STRING":
            return ('T', self.make_string_term(expr.get("value","")))
        if t=="PATTERN":
            return ('T', self.make_pattern_term(expr))
        if t in ("TOKEN","IMMEDIATE_TOKEN"):
            term=self.make_term_for_token_expr(expr, immediate=(t=="IMMEDIATE_TOKEN"))
            return ('T', term)
        if t=="BLANK":
            aux=self._new_aux("blank"); self._add_prod(aux, [], {"kind":"aux"}); return ('N', aux)
        # composite -> aux
        if t=="REPEAT" or t=="REPEAT1":
            aux=self._new_aux("repeat")
            content_el=self._element(expr.get("content",{}))
            rhs_content=[content_el] if content_el else []
            if t=="REPEAT":
                self._add_prod(aux, [], {"kind":"repeat"})
            # productions: content  | content aux (right recursive)
            # For repeat, also single content handled by content+aux(empty) but add direct for simpler building
            if rhs_content:
                self._add_prod(aux, rhs_content, {"kind":"repeat"})
                self._add_prod(aux, rhs_content+[('N',aux)], {"kind":"repeat"})
            return ('N', aux)
        if t=="FIELD":
            aux=self._new_aux("field"); self._expand(aux, expr.get("content",{}), {"kind":"field","name":expr.get("name")}); return ('N', aux)
        if t=="ALIAS":
            aux=self._new_aux("alias"); self._expand(aux, expr.get("content",{}), {"kind":"alias","value":expr.get("value"),"named":expr.get("named",False)}); return ('N', aux)
        if t in ("PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC","RESERVED","CHOICE","SEQ"):
            aux=self._new_aux("aux"); self._expand(aux, expr, {"kind":"aux"}); return ('N', aux)
        # fallback
        aux=self._new_aux("aux"); self._expand(aux, expr, {"kind":"aux"}); return ('N', aux)
    def _build_extra_specs(self):
        specs=[]
        for expr in self.extras_exprs:
            if not isinstance(expr,dict): continue
            t=expr.get("type")
            if t=="PATTERN":
                specs.append((compile_regex(expr.get("value",""), expr.get("flags","")), None, False))
            elif t=="STRING":
                specs.append((compile_regex(re.escape(expr.get("value",""))), expr.get("value",""), False))
            elif t=="SYMBOL":
                nm=expr.get("name")
                if nm in self.rules and self.is_token_rule(nm):
                    term=self.term_for_named_token(nm)
                    specs.append((term.regex, (nm if term.named else term.node_type), term.named))
                elif nm in self.rules:
                    # non-token extra rule: compile as token if possible
                    term=self.make_term_for_token_expr(self.rules[nm], node_type=nm, named=not nm.startswith("_"))
                    specs.append((term.regex, nm, not nm.startswith("_")))
                else:
                    specs.append((compile_regex(r".*"), nm, True))
            elif t in ("TOKEN","IMMEDIATE_TOKEN"):
                term=self.make_term_for_token_expr(expr)
                specs.append((term.regex, term.node_type if term.named else None, term.named))
            else:
                term=self.make_term_for_token_expr(expr)
                if term.regex: specs.append((term.regex, None, False))
        return specs

class EarleyParser:
    def __init__(self, grammar_dict, text):
        self.cg=CompiledGrammar(grammar_dict)
        self.text=text
        self.n=len(text)
        self.token_cache={}
        self.has_error=False
    # extras consumption: returns list of (extras_nodes, endpos) - greedy one option
    def consume_extras(self, pos):
        extras=[]; cur=pos
        while cur<self.n:
            matched=False
            for regex, node_type, named in self.cg.extra_specs:
                if regex is None: continue
                m=regex.match(self.text, cur)
                if m and m.end()>cur:
                    if node_type is not None:
                        extras.append(Node(node_type, named, cur, m.end(), extra=True, text_src=self.text))
                    cur=m.end(); matched=True; break
                elif m and m.end()==cur:
                    continue
            if not matched: break
        return extras, cur
    def scan_term(self, term, pos):
        key=(term.key, pos)
        if key in self.token_cache: return self.token_cache[key]
        results=[]
        if term.immediate:
            end=term.match(self.text, pos)
            if end is not None:
                node=Node(term.node_type, term.named, pos, end, text_src=self.text)
                node.leading=[]
                results.append((node,end))
        else:
            extras, cur=self.consume_extras(pos)
            end=term.match(self.text, cur) if cur<=self.n else None
            if end is not None:
                node=Node(term.node_type, term.named, cur, end, text_src=self.text)
                node.leading=[e.clone() for e in extras]
                results.append((node,end))
        self.token_cache[key]=results
        return results
    def parse(self):
        cg=self.cg
        if cg.start_rule is None:
            return None
        # wrapper element for start
        start_expr={"type":"SYMBOL","name":cg.start_rule}
        # Use internal run
        wrapper_name="__root__"
        # create wrapper prod temporarily in cg
        # Build element using cg._element but it may add aux prods; do before run and reindex
        el=cg._element(start_expr)
        wrapper_prod=Prod(wrapper_name, [el], {"kind":"root"})
        cg.prods.append(wrapper_prod)
        cg.prods_by_lhs={} 
        for idx,p in enumerate(cg.prods): cg.prods_by_lhs.setdefault(p.lhs,[]).append(idx)
        completed, charts = self._run(wrapper_name, 0)
        candidates=[]
        for (lhs,start,end), families in completed.items():
            if lhs==wrapper_name and start==0:
                extras, final=self.consume_extras(end)
                if final==self.n:
                    candidates.append((end, extras))
                elif end==self.n:
                    candidates.append((end, []))
        if candidates:
            # prefer longest end (all =?) build
            candidates.sort(key=lambda x: x[0])
            end, trailing = candidates[-1]
            res=self._build((wrapper_name,0,end), completed, set())
            if res and res.nodes:
                root=res.nodes[0]
                # root may be token or node; ensure children list
                # Insert leading
                leading=res.leading  # wrapper leading = root node's leading? root node itself stored leading inside? Wrapper BuildResult leading is child leading
                # res.nodes[0] may already be root; insert leading extras that are before root
                # Wrapper assembly: root wrapper is transparent, its first child leading becomes wrapper leading, not inserted. res.leading is that.
                children_prefix=[e.clone() for e in leading] if leading else []
                # If root is same as first token node, leading should become children prefix (if extras named)
                if children_prefix:
                    root.children = children_prefix + root.children
                    root.start = children_prefix[0].start
                if trailing:
                    root.children = root.children + [e.clone() for e in trailing]
                root.start = 0 if (self.text[:root.start].strip()=="" or children_prefix or root.start!=0) and False else root.start
                # Tree-sitter root spans whole file when trailing whitespace/comments consumed: set start to min(root.start, first token?) Keep original first node start except: if leading whitespace only, original root starts at 0.
                # Determine: if text before root.start consists only of extras (whitespace/comments already in children) set to 0 if file starts there? Simpler: if root is start_rule node, set start=0 when all preceding text is whitespace or extras consumed (it is, because parse started at 0 with extras). Actually extras before first token were stored as leading and inserted only if named; whitespace preceding still part of root span in tree-sitter (root starts at 0,0 generally).
                root.start = 0
                root.end = self.n
                # If root is a token leaf and had children added, fine
                return root
        # failure fallback
        self.has_error=True
        return self._fallback_parse(completed if 'completed' in locals() else {})
    def _run(self, start_lhs, origin):
        cg=self.cg; n=self.n
        # charts: list of dicts itemkey-> [prod,dot,origin, derivations(list), processed_count]
        charts=[]
        def ensure_chart(i):
            while len(charts)<=i: charts.append({})
        ensure_chart(origin)
        completed={}  # (lhs,start,end)-> set families
        completed_list={}
        work=[]  # (chart_index, itemkey)
        def add_item(chart_idx, prod_idx, dot, orig, derivation):
            ensure_chart(chart_idx)
            key=(prod_idx,dot,orig)
            chart=charts[chart_idx]
            if key not in chart:
                chart[key]=[prod_idx,dot,orig,[derivation],0]
                work.append((chart_idx,key))
            else:
                if derivation not in chart[key][3]:
                    chart[key][3].append(derivation)
                    work.append((chart_idx,key))
        # initial items
        for prod_idx in cg.prods_by_lhs.get(start_lhs,[]):
            add_item(origin, prod_idx, 0, origin, ())
        idx=0
        # Worklist may grow across charts; process in roughly chart order: we will loop scanning work list but ensure lower chart indices processed first by sorting periodically?
        # Simple index pointer; items added to future charts appended, items added to current/past charts also appended at end and will be processed.
        while idx < len(work):
            chart_idx, key = work[idx]; idx+=1
            ensure_chart(chart_idx)
            chart=charts[chart_idx]
            if key not in chart: continue
            item=chart[key]
            prod_idx,dot,orig,derivations,processed = item
            # process all unprocessed derivations
            while item[4] < len(item[3]):
                derivation=item[3][item[4]]; item[4]+=1
                prod=cg.prods[prod_idx]
                if dot < len(prod.rhs):
                    elem_kind, elem = prod.rhs[dot]
                    if elem_kind=='N':
                        # predict
                        for pidx in cg.prods_by_lhs.get(elem,[]):
                            add_item(chart_idx, pidx, 0, chart_idx, ())
                        # epsilon / already completed at same pos
                        fam_key=(elem, chart_idx, chart_idx)
                        if fam_key in completed:
                            for fam in list(completed[fam_key]):
                                add_item(chart_idx, prod_idx, dot+1, orig, derivation+(('N',elem,chart_idx,chart_idx),))
                        # also completed spanning to future already registered? (possible if chart_idx revisit) check any completed (elem,chart_idx,end)
                        for (lhs,s,e), fams in list(completed.items()):
                            if lhs==elem and s==chart_idx and e!=chart_idx:
                                for fam in list(fams):
                                    add_item(e, prod_idx, dot+1, orig, derivation+(('N',elem,s,e),))
                    else:
                        term=elem
                        for token_node, endpos in self.scan_term(term, chart_idx):
                            # store token node in a ref by identity: encode as ('T', token_node) - token node object hashable by id? Use object directly in tuple (Node defines no eq, hash by id default)
                            add_item(endpos, prod_idx, dot+1, orig, derivation+(('T', token_node),))
                else:
                    # complete
                    fam_key=(prod.lhs, orig, chart_idx)
                    fam=(prod_idx, derivation)
                    if fam_key not in completed:
                        completed[fam_key]=set(); completed_list[fam_key]=[]
                    if fam not in completed[fam_key]:
                        completed[fam_key].add(fam); completed_list[fam_key].append(fam)
                        # advance waiting items in origin chart
                        if orig < len(charts):
                            waiting=list(charts[orig].items())
                            for wkey, witem in waiting:
                                wprod=cg.prods[witem[0]]
                                if witem[1] < len(wprod.rhs):
                                    ek, ev = wprod.rhs[witem[1]]
                                    if ek=='N' and ev==prod.lhs:
                                        for wderiv in list(witem[3]):
                                            add_item(chart_idx, witem[0], witem[1]+1, witem[2], wderiv+(('N',prod.lhs,orig,chart_idx),))
            # loop derivations
        return completed_list, charts
    def _build(self, key, completed, stack):
        if key in stack: return None
        lhs,start,end=key
        families=completed.get(key,[])
        if not families: return None
        stack=set(stack); stack.add(key)
        best=None
        for prod_idx, derivation in families:
            prod=self.cg.prods[prod_idx]
            child_results=[]
            ok=True
            for ref in derivation:
                if ref[0]=='T':
                    token=ref[1]
                    cloned=token.clone()
                    res=BuildResult([cloned], leading=[e.clone() for e in token.leading], score=1)
                    child_results.append(res)
                else:
                    _, clhs, cs, ce = ref
                    sub=self._build((clhs,cs,ce), completed, stack)
                    if sub is None: ok=False; break
                    child_results.append(sub)
            if not ok: continue
            res=self._assemble(prod, child_results, start, end)
            if res is None: continue
            # scoring
            score=res.score + sum(cr.score for cr in child_results)
            if isinstance(prod.prec_value,(int,float)): score += prod.prec_value*0.1
            # associativity bonuses
            if prod.prec_kind in ("left","right") and derivation:
                refs=[r for r in derivation]
                if prod.prec_kind=="left" and refs:
                    first=refs[0]
                    if first[0]=='N':
                        # if first child's built node type equals lhs or its span large
                        if child_results and child_results[0].nodes and child_results[0].nodes[0].type==lhs:
                            score += (first[3]-first[2]) * 0.01
                if prod.prec_kind=="right" and refs:
                    last=refs[-1]
                    if last[0]=='N':
                        if child_results and child_results[-1].nodes and child_results[-1].nodes[0].type==lhs:
                            score += (last[3]-last[2]) * 0.01
            res.score=score
            if best is None or score>best.score:
                best=res
        return best
    def _assemble(self, prod, child_results, start, end):
        builder=prod.builder; kind=builder.get("kind")
        seq_nodes=[]; leading=[]
        for i, cr in enumerate(child_results):
            if cr.leading:
                if i==0:
                    leading.extend([e.clone() for e in cr.leading])
                else:
                    seq_nodes.extend([e.clone() for e in cr.leading])
            seq_nodes.extend(cr.nodes)
        if kind in ("aux","repeat","root"):
            return BuildResult(seq_nodes, leading=leading)
        if kind=="field":
            for node in seq_nodes: node.field=builder.get("name")
            return BuildResult(seq_nodes, leading=leading)
        if kind=="alias":
            if seq_nodes:
                main=seq_nodes[0]; main.type=builder.get("value"); main.named=bool(builder.get("named"))
            return BuildResult(seq_nodes, leading=leading)
        if kind=="rule":
            name=builder.get("name")
            if name.startswith("_") or name in self.cg.supertypes or name in self.cg.inline:
                return BuildResult(seq_nodes, leading=leading)
            if seq_nodes:
                s=seq_nodes[0].start; e=seq_nodes[-1].end
            else:
                s=start; e=end
            node=Node(name, True, s, e, children=seq_nodes, text_src=self.text)
            return BuildResult([node], leading=leading)
        return BuildResult(seq_nodes, leading=leading)
    def try_parse_symbol(self, element, pos):
        # element is ('N',name) or ('T',term)
        if element[0]=='T':
            res=self.scan_term(element[1], pos)
            if res:
                node,end=res[0]; return ([node.clone()], end, [e.clone() for e in node.leading])
            return None
        name=element[1]
        if name in self.cg.rules and self.cg.is_token_rule(name):
            res=self.scan_term(self.cg.term_for_named_token(name), pos)
            if res:
                node,end=res[0]; return ([node.clone()], end, [e.clone() for e in node.leading])
            return None
        wrapper="__sym__"
        # Add wrapper prod each time? Creating new wrapper per call may accumulate; create unique
        wrapper=f"__sym{abs(hash((name,pos)))%100000}__"
        el=('N',name)
        self.cg.prods.append(Prod(wrapper,[el],{"kind":"root"}))
        self.cg.prods_by_lhs={}
