import re, copy

class Node:
    __slots__=("type","named","start","end","children","field","extra","leading","text_src")
    def __init__(self, type, named, start, end, children=None, field=None, extra=False, text_src=""):
        self.type=type; self.named=named; self.start=start; self.end=end
        self.children=children or []; self.field=field; self.extra=extra; self.leading=[]; self.text_src=text_src
    @property
    def text(self):
        return self.text_src[self.start:self.end] if self.text_src else ""
    def clone(self):
        n=Node(self.type,self.named,self.start,self.end,[c.clone() for c in self.children],self.field,self.extra,self.text_src)
        n.leading=[c.clone() for c in self.leading]
        return n
    def all_nodes(self):
        yield self
        for c in self.children:
            yield from c.all_nodes()

def translate_pattern(pat):
    # basic \p translations
    pat = pat.replace(r"\p{L}", r"[^\W\d_]")
    pat = pat.replace(r"\p{Lu}", r"[A-Z]")
    pat = pat.replace(r"\p{Ll}", r"[a-z]")
    pat = pat.replace(r"\p{N}", r"\d")
    # JS \d etc compatible; \/ ok
    return pat

def compile_regex(pat, flags_str=""):
    flags=0
    if "i" in (flags_str or ""): flags|=re.I
    if "s" in (flags_str or ""): flags|=re.S
    if "m" in (flags_str or ""): flags|=re.M
    try:
        return re.compile(translate_pattern(pat), flags)
    except re.error:
        # try escaping unsupported constructs crudely
        try:
            return re.compile(translate_pattern(pat).replace(r"\z", r"\Z"), flags)
        except Exception:
            return re.compile(r"(?!)", flags)

class Term:
    __slots__=("key","node_type","named","regex","literal","immediate","prec","flags")
    def __init__(self, key, node_type, named, regex=None, literal=None, immediate=False, prec=0):
        self.key=key; self.node_type=node_type; self.named=named; self.regex=regex; self.literal=literal; self.immediate=immediate; self.prec=prec
    def match(self, text, pos):
        if self.literal is not None:
            if text.startswith(self.literal, pos): return pos+len(self.literal)
            return None
        if self.regex is not None:
            m=self.regex.match(text, pos)
            if m and m.end()>pos: return m.end()
            if m and m.end()==pos: return None
            return None
        return None

