def max_seq_len(grammar, cg):
    best=1
    def visit(expr):
        nonlocal best
        if not isinstance(expr,dict): return
        if expr.get("type")=="SEQ": best=max(best, len(expr.get("members",[]) or []))
        if "content" in expr: visit(expr["content"])
        for m in expr.get("members",[]) or []: visit(m)
    for e in (grammar.get("rules",{}) or {}).values(): visit(e)
    return best

