        for s in summaries:
            if fname in s.fields:
                types|=s.fields[fname]["types"]; mins.append(s.fields[fname]["min"]); maxs.append(s.fields[fname]["max"])
            else:
                mins.append(0); maxs.append(0)
        out.fields[fname]={"types":types,"min":min(mins),"max":max(maxs)}
    return out
def leaf_summary(type_, named, is_token):
    s=Summary(); s.nodes={(type_,named,is_token):(1,1)}; s.nodes_min=1; s.nodes_max=1; s.named_min=1 if named else 0; s.named_max=1 if named else 0; return s

class NodeTypeGen:
    def __init__(self, grammar):
        self.g=grammar; self.cg=CompiledGrammar(grammar)
        self.rules=grammar.get("rules",{}) or {}
        self.start=next(iter(self.rules), None)
        self.supertypes=list(grammar.get("supertypes",[]) or [])
        self.inline=set(grammar.get("inline",[]) or [])
        self._summary_cache={}
        self._in_progress=set()
        self.reachable=self._reachable()
    def _reachable(self):
        seen=set(); stack=[]
        if self.start: stack.append(self.start)
        for e in self.g.get("extras",[]) or []:
            self._symbols_in(e, stack)
        while stack:
            name=stack.pop()
            if name in seen or name not in self.rules: continue
            seen.add(name)
            self._symbols_in(self.rules[name], stack)
        return seen
    def _symbols_in(self, expr, out):
        if not isinstance(expr,dict): return
        t=expr.get("type")
        if t=="SYMBOL": out.append(expr.get("name"))
        for k in ("content",):
            if k in expr: self._symbols_in(expr[k], out)
        for k in ("members",):
            for m in expr.get(k,[]) or []: self._symbols_in(m, out)
    def analyze_rule(self, name):
        if name in self._summary_cache: return self._summary_cache[name]
        if name in self._in_progress: return Summary()
        self._in_progress.add(name)
        s=self.analyze(self.rules.get(name,{}))
        self._in_progress.remove(name)
        self._summary_cache[name]=s; return s
    def analyze(self, expr):
        if not isinstance(expr,dict): return Summary()
        t=expr.get("type")
        if t=="STRING": return leaf_summary(expr.get("value",""), False, True)
        if t=="PATTERN": return Summary()  # no node type
        if t=="BLANK": return Summary()
        if t=="SYMBOL":
            nm=expr.get("name")
            if nm in self.rules and self.cg.is_token_rule(nm):
                if nm.startswith("_"):
                    lit=self.cg._literal_from_expr(self.rules[nm])
                    if lit is not None: return leaf_summary(lit, False, True)
                    return Summary()
                return leaf_summary(nm, True, True)
            if nm in self.rules and (nm.startswith("_") or nm in self.inline):
                return self.analyze_rule(nm)
            if nm in self.supertypes:
                return leaf_summary(nm, True, False)
            # named internal or external
            return leaf_summary(nm, True, False)
        if t=="SEQ":
            out=Summary()
            for m in expr.get("members",[]): merge_seq(out, self.analyze(m))
            return out
        if t=="CHOICE":
            return merge_choice([self.analyze(m) for m in expr.get("members",[])])
        if t=="REPEAT":
            sub=self.analyze(expr.get("content",{})); out=Summary()
            out.nodes={k:(0, INF if v[1]>0 else 0) for k,v in sub.nodes.items()}
            out.nodes_min=0; out.nodes_max=INF if sub.nodes_max>0 else 0; out.named_min=0; out.named_max=INF if sub.named_max>0 else 0
            out.fields={k:{"types":set(v["types"]),"min":0,"max":INF if v["max"]>0 else 0} for k,v in sub.fields.items()}
            return out
        if t=="REPEAT1":
            sub=self.analyze(expr.get("content",{})); out=sub.copy()
            out.nodes={k:(v[0], INF if v[1]>0 else 0) for k,v in sub.nodes.items()}
            out.nodes_max=INF if sub.nodes_max>0 else 0; out.named_max=INF if sub.named_max>0 else 0
            for f in out.fields.values(): f["max"]=INF if f["max"]>0 else 0
            return out
        if t in ("PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC","RESERVED"):
            return self.analyze(expr.get("content",{}))
        if t in ("TOKEN","IMMEDIATE_TOKEN"):
            content=expr.get("content",{})
            lit=self.cg._literal_from_expr(content)
            if lit is not None: return leaf_summary(lit, False, True)
            if isinstance(content,dict) and content.get("type")=="SYMBOL":
                return self.analyze(content)
            if isinstance(content,dict) and content.get("type")=="PATTERN": return Summary()
            if isinstance(content,dict) and content.get("type")=="STRING": return leaf_summary(content.get("value",""), False, True)
            return Summary()
        if t=="FIELD":
            sub=self.analyze(expr.get("content",{})); out=Summary()
            # fields inside sub remain, plus this field
            out.fields={k:{"types":set(v["types"]),"min":v["min"],"max":v["max"]} for k,v in sub.fields.items()}
            fname=expr.get("name")
            out.fields[fname]={"types":set(sub.nodes.keys()),"min":sub.nodes_min,"max":sub.nodes_max}
            return out
        if t=="ALIAS":
            sub=self.analyze(expr.get("content",{})); out=sub.copy()
            val=expr.get("value"); named=bool(expr.get("named"))
            new_nodes={}
            for (typ,nm,is_tok),(mn,mx) in sub.nodes.items():
                key=(val, named, is_tok); new_nodes[key]=add_qty(new_nodes.get(key,(0,0)), (mn,mx))
            out.nodes=new_nodes
            out.named_min=sub.named_min if named else 0; out.named_max=sub.named_max if named else 0
            # also update field type sets? Field types referencing old types inside sub fields are nested fields, leave.
            return out
        return Summary()
    def generate(self):
        entries=[]
        # supertypes first
        for st in self.supertypes:
            if st not in self.rules: continue
            s=self.analyze_rule(st)
            subtypes=[{"type":typ,"named":named} for (typ,named,is_tok) in sorted(s.nodes.keys(), key=lambda x: x[0])]
            # subtypes sorted by type
            subtypes=sorted(subtypes, key=lambda x: x["type"])
            entries.append({"type":st,"named":True,"subtypes":subtypes})
        internal=[]
        token_types={}  # (type,named)-> extra bool
        extra_named=set()
        for e in self.g.get("extras",[]) or []:
            if isinstance(e,dict) and e.get("type")=="SYMBOL":
                nm=e.get("name")
                if nm in self.rules and self.cg.is_token_rule(nm) and not nm.startswith("_"): extra_named.add(nm)
        for name in sorted(self.reachable):
            if name.startswith("_") or name in self.inline or name in self.supertypes: continue
            is_root=(name==self.start)
            if self.cg.is_token_rule(name) and not is_root:
                token_types[(name,True)]=name in extra_named
                continue
            # internal
            s=self.analyze_rule(name)
            entry={"type":name,"named":True}
            if is_root: entry["root"]=True
            fields={}
            for fname in sorted(s.fields.keys()):
                f=s.fields[fname]
                types=[{"type":typ,"named":named} for (typ,named,is_tok) in f["types"]]
                types=sorted(types, key=lambda x: x["type"])
                fields[fname]={"multiple": f["max"]>1, "required": f["min"]>0, "types": types}
                for (typ,named,is_tok) in f["types"]:
                    if is_tok: token_types[(typ,named)]=token_types.get((typ,named), False)
            entry["fields"]=fields
            child_types=[{"type":typ,"named":named} for (typ,named,is_tok) in s.nodes.keys() if named]
            child_types=sorted(child_types, key=lambda x: x["type"])
            for (typ,named,is_tok) in s.nodes.keys():
                if is_tok: token_types[(typ,named)]=token_types.get((typ,named), False)
            if child_types:
                entry["children"]={"multiple": s.named_max>1, "required": s.named_min>0, "types": child_types}
            internal.append(entry)
        entries.extend(internal)  # already sorted due reachable sorted iteration (supertypes excluded)
        # token types from extras token rules that may not be reachable as internal nodes?
        for nm in extra_named:
            token_types[(nm,True)]=True
        # Also token rules reachable but not captured? Add named token rules referenced
        for name in self.reachable:
            if name in self.supertypes or name.startswith("_"): continue
            if self.cg.is_token_rule(name) and name!=self.start:
                token_types.setdefault((name,True), name in extra_named)
        for (typ,named) in sorted(token_types.keys(), key=lambda x: x[0]):
            e={"type":typ,"named":named}
            if token_types[(typ,named)]: e["extra"]=True
            entries.append(e)
        return entries

def generate_node_types(grammar):
    return NodeTypeGen(grammar).generate()

