CHAR_NAMES={"!":"BANG",'"':"DQUOTE","#":"HASH","$":"DOLLAR","%":"PERCENT","&":"AMP","'":"SQUOTE","(":"LPAREN",")":"RPAREN","*":"STAR","+":"PLUS",",":"COMMA","-":"MINUS",".":"DOT","/":"SLASH",":":"COLON",";":"SEMI","<":"LT","=":"EQ",">":"GT","?":"QUEST","@":"AT","[":"LBRACK","\\":"BSLASH","]":"RBRACK","^":"CARET","_":"UNDERSCORE","`":"BQUOTE","{":"LBRACE","|":"PIPE","}":"RBRACE","~":"TILDE"," ":"SPACE"}
def anon_name_for(s):
    if s and all(ch.isalnum() for ch in s):
        return "anon_sym_"+s
    parts=[]
    for ch in s:
        if ch.isalnum(): parts.append(ch)
        else: parts.append(CHAR_NAMES.get(ch, f"U{ord(ch):X}"))
    return "anon_sym_"+"_".join(parts) if parts else "anon_sym_EMPTY"
def c_escape(s):
    return s.replace("\\","\\\\").replace('"','\\"').replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")
def sanitize_ident(s):
    return re.sub(r'[^A-Za-z0-9_]', '_', s)

def collect_symbols(grammar, cg):
    tokens=[]  # (enum_name, display_name, named, visible)
    seen=set()
    def add_token(enum_name, disp, named, visible=True):
        if disp in seen and not named: 
            # named tokens key by disp also
            pass
        key=(disp,named)
        if key in seen: return
        seen.add(key); tokens.append((enum_name,disp,named,visible))
    def traverse(expr, current_rule=None):
        if not isinstance(expr,dict): return
        t=expr.get("type")
        if t=="STRING":
            v=expr.get("value",""); add_token(anon_name_for(v), v, False, True); return
        if t=="PATTERN": return
        if t in ("TOKEN","IMMEDIATE_TOKEN"):
            # if inside named non-token rule, anonymous token approximated by literal
            lit=cg._literal_from_expr(expr)
            if lit is not None: add_token(anon_name_for(lit), lit, False, True)
            return
        for k in ("content",):
            if k in expr: traverse(expr[k], current_rule)
        for m in expr.get("members",[]) or []: traverse(m, current_rule)
    for name, expr in (grammar.get("rules",{}) or {}).items():
        if cg.is_token_rule(name):
            if not name.startswith("_"):
                add_token("sym_"+sanitize_ident(name), name, True, True)
            else:
                lit=cg._literal_from_expr(expr)
                if lit is not None: add_token(anon_name_for(lit), lit, False, True)
            continue
        traverse(expr, name)
    # extras tokens
    for e in grammar.get("extras",[]) or []:
        if isinstance(e,dict) and e.get("type")=="SYMBOL":
            nm=e.get("name")
            if nm in cg.rules and cg.is_token_rule(nm) and (nm,True) not in seen:
                add_token("sym_"+sanitize_ident(nm), nm, True, True)
    nonterms=[]
    for name in (grammar.get("rules",{}) or {}):
        if cg.is_token_rule(name): continue
        nonterms.append(("sym_"+sanitize_ident(name), name, True, not name.startswith("_")))
    aux=[]
    aux_seen=set()
    def find_repeats(expr, rule):
        if not isinstance(expr,dict): return
        if expr.get("type") in ("REPEAT","REPEAT1"):
            nm=f"{rule}_repeat1"
            if nm not in aux_seen:
                aux_seen.add(nm); aux.append((f"aux_sym_{sanitize_ident(nm)}", nm, False, False))
        if "content" in expr: find_repeats(expr["content"], rule)
        for m in expr.get("members",[]) or []: find_repeats(m, rule)
    for name, expr in (grammar.get("rules",{}) or {}).items():
        if not cg.is_token_rule(name): find_repeats(expr, name)
    symbols=[("ts_builtin_sym_end","end",True,False)]+tokens+nonterms+aux
    fields=[]; fseen=set()
    def find_fields(expr):
        if not isinstance(expr,dict): return
        if expr.get("type")=="FIELD":
            nm=expr.get("name")
            if nm not in fseen: fseen.add(nm); fields.append(nm)
        if "content" in expr: find_fields(expr["content"])
        for m in expr.get("members",[]) or []: find_fields(m)
    for expr in (grammar.get("rules",{}) or {}).values(): find_fields(expr)
    return symbols, fields

def max_seq_len(grammar, cg):
    best=1
    def visit(expr):
        nonlocal best
        if not isinstance(expr,dict): return
        if expr.get("type")=="SEQ": best=max(best, len(expr.get("members",[]) or []))
        if "content" in expr: visit(expr["content"])
        for m in expr.get("members",[]) or []: visit(m)
    for e in (grammar.get("rules",{}) or {}).values(): visit(e)
    return best

def generate_parser_c(grammar, abi=15, version=None):
    cg=CompiledGrammar(grammar)
    symbols, fields=collect_symbols(grammar, cg)
