def collect_valid_types(grammar):
    types=set(["ERROR","_"])
    fields=set()
    anon=set()
    for name in (grammar.get("rules",{}) or {}): types.add(name)
    def walk(e):
        if not isinstance(e,dict): return
        t=e.get("type")
        if t=="STRING": types.add(e.get("value","")); anon.add(e.get("value",""))
        if t=="ALIAS": types.add(e.get("value",""))
        if t=="FIELD": fields.add(e.get("name"))
        if "content" in e: walk(e["content"])
        for m in e.get("members",[]) or []: walk(m)
    for e in (grammar.get("rules",{}) or {}).values(): walk(e)
    return types, fields, anon

