def serde_json_error(text, exc=None):
    if exc is not None:
        msg=str(exc)
        # map python messages
        line=getattr(exc,'lineno',1); col=getattr(exc,'colno',1)
        if "Expecting value" in msg:
            if text.strip() and text.lstrip()[0].isalpha() and not text.lstrip().startswith(("true","false","null")):
                return "expected ident at line 1 column 2"
            return f"expected value at line {line} column {col}"
        if "property name" in msg: return f"key must be a string at line {line} column {col}"
        if "Extra data" in msg: return f"trailing characters at line {line} column {col}"
        if "Expecting ':'" in msg: return f"expected `:` at line {line} column {col}"
        if "Expecting ','" in msg: return f"expected `,` or `}}` at line {line} column {col}"
        return f"{msg} at line {line} column {col}"
    return "expected value at line 1 column 1"

def parse_json_text(text):
    return json.loads(text)

class Lang:
    def __init__(self, name, scope="", file_types=None, highlights=None, tags=None, content_regex=None, injection_regex=None, parser_dir=None, display_parser=None, camelcase=None, class_name=None):
        self.name=name; self.scope=scope or ""; self.file_types=file_types or []
        self.highlights=highlights; self.tags=tags; self.content_regex=content_regex; self.injection_regex=injection_regex
        self.parser_dir=Path(parser_dir) if parser_dir else None
        self.display_parser=display_parser or (str(parser_dir) if parser_dir else "")
        self.camelcase=camelcase; self.class_name=class_name
        self._grammar=None
    def grammar_path_candidates(self):
        if not self.parser_dir: return []
        cands=[self.parser_dir/"src"/"grammar.json", self.parser_dir/"src"/self.name/"grammar.json", self.parser_dir/"grammar.json"]
        return cands
    def grammar_json_path(self):
        for c in self.grammar_path_candidates():
            if c.exists(): return c
        return self.grammar_path_candidates()[0] if self.grammar_path_candidates() else None
    def load_grammar(self, context_path=None, grammar_path_display=None):
        if self._grammar is not None: return self._grammar
        gp=self.grammar_json_path()
        if gp is None or not gp.exists():
            shown=grammar_path_display or (str(gp) if gp else "")
            raise AppError(f'Failed to load language for path "{context_path}"' if context_path else "Failed to load language", cause=f"No such file or directory (os error 2) ({shown})")
        try:
            self._grammar=json.loads(gp.read_text(encoding="utf-8"))
        except Exception as e:
            raise AppError(f'Failed to load language for path "{context_path}"' if context_path else "Failed to load language", cause=str(e))
        return self._grammar

