def load_config(explicit=None):
    path=config_path(explicit)
    if explicit and not Path(explicit).exists():
        raise AppError(f"No such file or directory (os error 2) ({explicit})")
    if not path.exists():
        return Config(path, {}, exists=False)
    try:
        text=path.read_text(encoding="utf-8")
        data=json.loads(text) if text.strip() else {}
    except json.JSONDecodeError as e:
        raise AppError(f"Bad JSON config {path} -- {serde_json_error(path.read_text(encoding='utf-8',errors='replace'), e)}")
    except OSError as e:
        raise AppError(f"No such file or directory (os error 2) ({explicit or path})")
    if not isinstance(data,dict): data={}
    return Config(path, data, exists=True)

def ts_config_error_message(text, data):
    # returns None if ok else serde-like missing field message
    # column approx: last non-whitespace char position (1-indexed col on its line)
    def end_col_line():
        lines=text.splitlines() or [""]
        for idx in range(len(lines)-1,-1,-1):
            if lines[idx].strip():
                return (idx+1, len(lines[idx].rstrip()))
        return (1,1)
    if not isinstance(data,dict): return "invalid type at line 1 column 1"
    line,col=end_col_line()
    if "grammars" not in data: return f"missing field `grammars` at line {line} column {col}"
    if "metadata" not in data: return f"missing field `metadata` at line {line} column {col}"
    meta=data.get("metadata")
    if isinstance(meta,dict):
        if "version" not in meta: return f"missing field `version` at line {line} column {col}"
        links=meta.get("links")
        if isinstance(links,dict) and "repository" not in links: return f"missing field `repository` at line {line} column {col}"
        authors=meta.get("authors")
        if isinstance(authors,list):
            for a in authors:
                if isinstance(a,dict) and "name" not in a: return f"missing field `name` at line {line} column {col}"
    grams=data.get("grammars")
    if isinstance(grams,list):
        for g in grams:
            if isinstance(g,dict) and "name" not in g: return f"missing field `name` at line {line} column {col}"
    return None

def parse_ts_config_file(path):
    text=Path(path).read_text(encoding="utf-8")
    try: data=json.loads(text)
    except json.JSONDecodeError as e: raise ValueError(serde_json_error(text,e))
    err=ts_config_error_message(text,data)
    if err: raise ValueError(err)
    return data

def langs_from_ts_data(data, parser_dir, display_parser):
    out=[]
    for g in data.get("grammars",[]) or []:
        if not isinstance(g,dict): continue
        highlights=g.get("highlights")
        if isinstance(highlights,str): highlights=[highlights]
        elif highlights is not None and not isinstance(highlights,list): highlights=[str(highlights)]
        tags=g.get("tags")
        if isinstance(tags,str): tags=[tags]
        elif tags is not None and not isinstance(tags,list): tags=[str(tags)]
        out.append(Lang(name=g.get("name",""), scope=g.get("scope",""), file_types=g.get("file-types",[]) or [], highlights=highlights, tags=tags, content_regex=g.get("content-regex"), injection_regex=g.get("injection-regex"), parser_dir=parser_dir, display_parser=display_parser, camelcase=g.get("camelcase"), class_name=g.get("class-name")))
    return out

_discovery_warned=False
def discover_languages(cfg, warn_empty=True):
    global _discovery_warned
    if warn_empty and not cfg.parser_directories and not _discovery_warned:
        warn_no_config(); _discovery_warned=True
    langs=[]
    for raw_dir in cfg.parser_directories:
        base=Path(raw_dir)
        if not base.is_dir(): continue
        try: entries=sorted(base.iterdir(), key=lambda p:p.name)
        except OSError: continue
        for entry in entries:
            if not entry.is_dir(): continue
            if not entry.name.startswith("tree-sitter-"): continue
            tsjson=entry/"tree-sitter.json"
            if tsjson.exists():
                try:
                    data=parse_ts_config_file(tsjson)
                except Exception as e:
                    warn(f"Failed to parse {entry}/tree-sitter.json -- {e}")
                    continue
                display=f"{entry}/."
                langs.extend(langs_from_ts_data(data, entry, display))
            else:
                name=None
                gj=entry/"src"/"grammar.json"
                if gj.exists():
                    try: name=json.loads(gj.read_text()).get("name")
                    except: pass
                if not name: name=entry.name[len("tree-sitter-"):]
                langs.append(Lang(name=name, scope="", file_types=[], parser_dir=entry, display_parser=str(entry)))
    return langs

def lang_from_grammar_dir(grammar_dir, select_name=None, select_ext=None):
    gd=Path(grammar_dir)
    tsjson=gd/"tree-sitter.json"
    if tsjson.exists():
        try: data=parse_ts_config_file(tsjson)
        except Exception as e:
            raise AppError(f"Failed to parse `{gd.resolve() if gd.exists() else gd}/tree-sitter.json` -- {e}")
        langs=langs_from_ts_data(data, gd, f"{gd}/.")
        if not langs: raise AppError("No language found")
        if select_name:
            for l in langs:
                if l.name==select_name: return l
        if select_ext:
            for l in langs:
                if select_ext in l.file_types: return l
        return langs[0]
    # no ts config
    gj=gd/"src"/"grammar.json"
    name=None
    if gj.exists():
        try: name=json.loads(gj.read_text()).get("name")
        except: pass
    if not name:
        base=gd.name
        name=base[len("tree-sitter-"):] if base.startswith("tree-sitter-") else base
    return Lang(name=name, scope=f"source.{name}", file_types=[name], parser_dir=gd, display_parser=str(gd))

def ensure_grammar_files(lang, context_path=None, context_kind="config"):
    # validates grammar.json and parser.c existence like original loader
    gp=lang.grammar_json_path()
    if gp is None or not gp.exists():
        if context_kind=="current":
            shown=f"{lang.parser_dir}/./src/grammar.json"
            raise AppError(f'Failed to load language for path "{context_path}"', cause=f"Failed to load language in current directory:\nNo such file or directory (os error 2) ({shown})")
        if context_kind=="grammar_path":
            base=str(lang.parser_dir)
            shown=f"{base}/./src/grammar.json"
            raise AppError(f'Failed to load language for path "{context_path}"', cause=f"Failed to load language in current directory:\nNo such file or directory (os error 2) ({shown})")
        raise AppError(f'Failed to load language for path "{context_path}"' if context_path else "Failed to load language", cause=f"No such file or directory (os error 2) ({gp})")
    pc=gp.parent/"parser.c"
    if not pc.exists():
        if context_kind in ("current","grammar_path"):
            shown=f"{lang.parser_dir}/./src/parser.c"
            raise AppError(f'Failed to load language for path "{context_path}"', cause=f"Failed to load language in current directory:\nFailed to compare binary and source timestamps:\nNo such file or directory (os error 2) ({shown})")
        # for config languages, still require parser.c in src dir of grammar.json
        raise AppError(f'Failed to load language for path "{context_path}"' if context_path else "Failed to load language", cause=f"Failed to compare binary and source timestamps:\nNo such file or directory (os error 2) ({pc})")
    return gp

def select_language(path_str, opts, cfg, langs):
    # opts dict with grammar_path, lib_path, lang_name, scope
    if opts.get("lib_path"):
        return select_language_lib(path_str, opts, cfg, langs)
    if opts.get("grammar_path"):
        lang=lang_from_grammar_dir(opts["grammar_path"])
        ensure_grammar_files(lang, context_path=path_str, context_kind="grammar_path")
        return lang
    if opts.get("scope"):
        scope=opts["scope"]
        for l in langs:
            if l.scope==scope: 
                ensure_grammar_files(l, context_path=path_str, context_kind="config")
                return l
        raise AppError(f'Failed to load language for path "{path_str}"', cause=f"Unknown scope '{scope}'")
    # by extension / filename
    p=Path(path_str) if path_str else None
    ext=p.suffix[1:] if p and p.suffix else ""
    basename=p.name if p else ""
    candidates=[l for l in langs if ext and ext in (l.file_types or []) or (basename and basename in (l.file_types or []))]
    if len(candidates)>1:
        # content regex on first line
        chosen=None
        if p and p.exists():
            try: first=p.read_bytes().splitlines()[0].decode(errors="replace") if p.read_bytes() else ""
            except: first=""
            for l in candidates:
                if l.content_regex:
                    try:
                        if re.search(l.content_regex, first): chosen=l; break
                    except: pass
        if chosen is None: chosen=candidates[0]
        ensure_grammar_files(chosen, context_path=path_str, context_kind="config"); return chosen
    if len(candidates)==1:
        ensure_grammar_files(candidates[0], context_path=path_str, context_kind="config"); return candidates[0]
    # fallback to current dir grammar if it looks like one
    cwd=Path.cwd()
    if (cwd/"tree-sitter.json").exists() or (cwd/"src"/"grammar.json").exists():
        lang=lang_from_grammar_dir(cwd)
        ensure_grammar_files(lang, context_path=path_str, context_kind="current")
        return lang
    raise AppError(f'Failed to load language for path "{path_str}"' if path_str else "No language found", cause="No language found" if path_str else None)

def select_language_lib(path_str, opts, cfg, langs):
    lib=opts["lib_path"]; lang_name=opts.get("lang_name")
    libpath=Path(lib)
    stem=libpath.stem
    if stem.startswith("lib"): stem=stem[3:]
    name=(lang_name or stem).replace("-","_")
    # file existence and symbol check
    if not libpath.exists():
        raise AppError(f'Failed to load language for path "{path_str}"', cause=f"Error opening dynamic library {lib} -- dlopen failed")
    # symbol check via ctypes if possible
    symbol=f"tree_sitter_{name}"
    symbol_ok=None
    try:
        import ctypes
        cdll=ctypes.CDLL(str(libpath))
        symbol_ok=hasattr(cdll, symbol)
    except Exception:
        symbol_ok=False
        # if CDLL fails due format, treat as dlopen failed?
        raise AppError(f'Failed to load language for path "{path_str}"', cause=f"Failed to load symbol {symbol} from {libpath} -- dlsym failed")
    if not symbol_ok:
        raise AppError(f'Failed to load language for path "{path_str}"', cause=f"Failed to load symbol {symbol} from {lib} -- dlsym failed")
    # find grammar: near lib, config by name, cwd
    search_dirs=[]
    if libpath.parent: search_dirs.append(libpath.parent)
    for d in search_dirs:
        gj=d/"src"/"grammar.json"
        if gj.exists():
            lang=lang_from_grammar_dir(d)
            # override name
            return lang
    for l in langs:
        if l.name.replace("-","_")==name:
            ensure_grammar_files(l, context_path=path_str, context_kind="config"); return l
    cwd=Path.cwd()
    if (cwd/"src"/"grammar.json").exists():
        lang=lang_from_grammar_dir(cwd); return lang
    raise AppError(f'Failed to load language for path "{path_str}"', cause=f"Failed to load symbol {symbol} from {lib} -- dlsym failed")

# ---------- points & tree formatting ----------
def point_of(text, idx):
    row=text.count("\n",0,idx)
    line_start=text.rfind("\n",0,idx)+1
    col=len(text[line_start:idx].encode("utf-8"))
    return (row,col)
def fmt_point(text, idx):
    r,c=point_of(text, idx); return f"[{r}, {c}]"

def visible_children(node):
    return [c for c in node.children if c.named]
def sexp(node, text, no_ranges=False, show_fields=True):
    # returns string (possibly multiline) starting at 0 indent; caller handles indents via lines
    lines=sexp_lines(node, text, no_ranges, show_fields, indent=0)
    return "\n".join(lines)
def sexp_lines(node, text, no_ranges, show_fields, indent):
    ind="  "*indent
    label=f"{node.field}: " if (show_fields and node.field) else ""
    rng="" if no_ranges else f" {fmt_point(text,node.start)} - {fmt_point(text,node.end)}"
    kids=[c for c in node.children if c.named]
    if not kids:
        return [f"{ind}{label}({node.type}{rng})"]
    lines=[f"{ind}{label}({node.type}{rng}"]
    for c in kids:
        lines.extend(sexp_lines(c, text, no_ranges, show_fields, indent+1))
    lines[-1]+=")"
    return lines

def sexp_one_line(node, text, show_fields=True):
    # one-line stripped fields (?) used in JSON failures compare: original one-line has no field labels if show_fields false; caller decides
    parts=[]
    def rec(n):
        s=f"({n.type}"
        for c in n.children:
            if c.named:
                s+=" "; 
                if show_fields and c.field: s+=f"{c.field}: "
                s+=rec(c)
        s+=")"; return s
    return rec(node)

def find_first_error(node):
    if node.type=="ERROR": return node
    for c in node.children:
        r=find_first_error(c)
        if r: return r
    return None
def has_error(node):
    if node.type=="ERROR": return True
    if node.type=="MISSING": return True
    return any(has_error(c) for c in node.children)

# ---------- files/paths handling ----------
def expand_paths(path_args, paths_file=None):
    result=[]
    if paths_file:
        pf=Path(paths_file)
        if not pf.exists():
            raise AppError(f"No such file or directory (os error 2) ({paths_file})")
        lines=pf.read_text(errors="replace").splitlines()
        for line in lines:
            line=line.strip()
            if line: result.extend(expand_one_path(line))
        return result
    for a in path_args:
        result.extend(expand_one_path(a))
    return result
def expand_one_path(a):
    # glob if contains magic
    if any(ch in a for ch in "*?["):
        matches=sorted(globmod.glob(a, recursive=True))
        return matches
    return [a]
def ensure_files_exist(files):
    if not files:
        raise AppError("No files were found at or matched by the provided pathname/glob")
    # also if a glob gave nothing already handled; explicit file existence checked at read time except glob magic already empty
    return files
def read_source_file(path_str):
    p=Path(path_str)
    if p.is_dir():
        raise AppError(f'Error reading "{path_str}"', cause="Is a directory (os error 21)")
    try:
        return p.read_bytes()
    except FileNotFoundError:
        # if path came from glob expansion it exists; explicit missing would have been treated as glob failure earlier in original when no matches? Original parse nonexistent.mylang gave No files... That occurs because paths are matched via glob-like search even without magic and file missing counts as no file.
        raise AppError("No files were found at or matched by the provided pathname/glob")
    except IsADirectoryError:
        raise AppError(f'Error reading "{path_str}"', cause="Is a directory (os error 21)")
    except OSError as e:
        raise AppError(f'Error reading "{path_str}"', cause=f"{e.strerror} (os error {e.errno})")
def collect_input_files(opts_vals, positional_paths, allow_stdin=True):
    # returns list of (display_name_or_None, bytes) ; reads stdin if no paths and stdin not tty
    files=[]
    if opts_vals.get("paths"):
        paths=expand_paths([], opts_vals.get("paths"))
        if not paths: raise AppError("No files were found at or matched by the provided pathname/glob")
        for p in paths:
            files.append((p, read_source_file(p)))
        return files
    if positional_paths:
        paths=expand_paths(positional_paths, None)
        if not paths: raise AppError("No files were found at or matched by the provided pathname/glob")
        for p in paths:
            # explicit non-glob missing file: if original path had no glob magic and file missing -> no files error
            if not Path(p).exists() and not any(ch in p for ch in "*?["):
                raise AppError("No files were found at or matched by the provided pathname/glob")
            files.append((p, read_source_file(p)))
        return files
    if allow_stdin and not sys.stdin.isatty():
        data=sys.stdin.buffer.read()
        return [(None, data)]
    raise AppError("No files were found at or matched by the provided pathname/glob")

def decode_source(data, encoding="utf8"):
    if encoding=="utf16-le": return data.decode("utf-16-le", errors="replace")
    if encoding=="utf16-be": return data.decode("utf-16-be", errors="replace")
    return data.decode("utf-8", errors="replace")

