def timing_line(name, duration_ns, byte_count, text, tree, is_error=False):
    ms=duration_ns/1_000_000
    speed=int(byte_count/ms) if ms>0 else byte_count*1000000
    line=f"{name}\tParse: {ms:7.2f} ms\t{speed:6d} bytes/ms"
    if is_error:
        err=find_first_error(tree)
        if err: line+=f"\t(ERROR {fmt_point(text,err.start)} - {fmt_point(text,err.end)})"
    return line
