# ---------- version ----------
def read_ts_for_version(grammar_dir):
    path=Path(grammar_dir)/"tree-sitter.json"
    if not path.exists():
        raise AppError("No such file or directory (os error 2)")
    text=path.read_text(encoding="utf-8")
    try: data=json.loads(text)
    except json.JSONDecodeError as e: raise AppError(serde_json_error(text,e))
    err=ts_config_error_message(text,data)
    if err: raise AppError(err)
    meta=data.get("metadata",{})
    ver=meta.get("version")
    if not isinstance(ver,str):
        raise AppError("invalid type at line 1 column 1")
    if semver_error_detail(ver):
        # locate version string in text to compute line/col of its closing quote
        # find "version" then following quoted string
        m=re.search(r'"version"\s*:\s*"([^"]*)"', text)
        if m:
            end_idx=m.end(1)+1  # closing quote index+1
            before=text[:end_idx]; line=before.count("\n")+1; col=len(before.splitlines()[-1]) if before.splitlines() else end_idx
            raise AppError(f"{semver_error_detail(ver)} at line {line} column {col}")
        raise AppError(semver_error_detail(ver))
    return path, text, data, ver

def bump_version(cur, level):
    major,minor,patch=[int(x) for x in cur.split("-")[0].split("+")[0].split(".")]
    if level=="patch": patch+=1
    elif level=="minor": minor+=1; patch=0
    elif level=="major": major+=1; minor=0; patch=0
    return f"{major}.{minor}.{patch}"

def replace_version_in_file(path, old, new, pattern_template, errors, mandatory=False, display_dir=None):
    p=Path(path)
    if not p.exists():
        if mandatory:
            errors.append((p, "No such file or directory (os error 2)"))
        return
    try:
        content=p.read_text(encoding="utf-8")
        pattern=pattern_template.replace("{old}", re.escape(old))
        if re.search(pattern, content):
            content2=re.sub(pattern, lambda m: m.group(0).replace(old,new), content, count=1)
            if content2!=content: p.write_text(content2, encoding="utf-8")
    except OSError as e:
        errors.append((p, f"{e.strerror} (os error {e.errno})"))

def cmd_version(vals, pos):
    grammar_dir=vals.get("grammar_path") or "."
    path, text, data, cur = read_ts_for_version(grammar_dir)
    target=None
    if pos: target=pos[0]
    elif vals.get("bump"):
        target=bump_version(cur, vals["bump"])
    if vals.get("bump") and pos:
        # handled by clap conflict below in main? implement here check (spec can't)
        pass
    if target is None:
        wprint(f"Current version: {cur}")
        return 0
    # validate target semver manually (positional already)
    eprint(f"Bumping version {cur} to {target}")
    errors=[]
    base=Path(grammar_dir).resolve()
    # update tree-sitter.json by replacing version value only
    new_text=re.sub(r'("version"\s*:\s*")'+re.escape(cur)+r'(")', r'\g<1>'+target+r'\g<2>', text, count=1)
    # In metadata only: first occurrence could be elsewhere; tree-sitter.json version appears in metadata; if multiple, search metadata section - use last? Original uses parsed update and re-serialize?? observed preserves formatting, so use occurrence after "metadata"
    if new_text==text:
        # try any version string
        new_text=re.sub(r'("version"\s*:\s*")[^"]*(")', r'\g<1>'+target+r'\g<2>', text, count=1)
    try:
        path.write_text(new_text, encoding="utf-8")
    except OSError as ex:
        errors.append((path, f"{ex.strerror} (os error {ex.errno})"))
    gd=base
    replace_version_in_file(gd/"Makefile", cur, target, r'VERSION := {old}', errors, mandatory=True)
    replace_version_in_file(gd/"CMakeLists.txt", cur, target, r'VERSION "{old}"', errors, mandatory=False)
    replace_version_in_file(gd/"Cargo.toml", cur, target, r'version = "{old}"', errors, mandatory=False)
    replace_version_in_file(gd/"package.json", cur, target, r'"version": "{old}"', errors, mandatory=False)
    replace_version_in_file(gd/"pyproject.toml", cur, target, r'version = "{old}"', errors, mandatory=False)
    replace_version_in_file(gd/"build.zig.zon", cur, target, r'\.version = "{old}"', errors, mandatory=False)
    if errors:
        body=""
        for p,msg in errors:
            body+=f"Failed to update {p}:\n{msg}\n\n"
        raise AppError("Failed to update one or more files:", body=body)
    return 0

