def load_grammar_via_runtime(grammar_file, runtime, grammar_dir):
    if runtime=="native":
        if not grammar_file.exists():
            raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- No such file or directory (os error 2) ({grammar_file})")
        try: text=grammar_file.read_text(encoding="utf-8")
        except OSError as e: raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- {e.strerror} (os error {e.errno}) ({grammar_file})")
        try:
            return load_grammar_js(text), None
        except JSError as e:
            cause=f"Failed to load grammar.js -- QuickJS error: Message: {e.message}\nStack:     at grammar.js:1:1\n\nType: {e.typ}"
            raise AppError("Error when generating parser", cause=cause)
        except Exception as e:
            # Python-level js parse errors that are tokenize/parser JSError already handled; syntax errors from parser raise JSError
            raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- QuickJS error: Message: {e}\nStack:     at grammar.js:1:1\n\nType: SyntaxError")
    # external runtime
    exe=shutil.which(runtime) if "/" not in runtime else runtime
    if not exe or not Path(exe).exists():
        raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- Failed to run `{runtime}` -- No such file or directory (os error 2)")
    env=dict(os.environ); env["TREE_SITTER_GRAMMAR_PATH"]=str(Path(grammar_file).resolve() if grammar_file.exists() else grammar_file.absolute())
    try:
        proc=subprocess.run([runtime], input=OUR_JS_LOADER, text=True, capture_output=True, env=env)
    except FileNotFoundError:
        raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- Failed to run `{runtime}` -- No such file or directory (os error 2)")
    if proc.returncode!=0:
        raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- `{runtime}` process exited with status {proc.returncode}")
    try:
        return json.loads(proc.stdout), None
    except Exception as e:
        raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- {proc.stdout[:200]}")

def cmd_generate(vals, pos):
    if vals.get("json") and not vals.get("json_summary"):
        warn("--json is deprecated, use --json-summary instead")
    arg=pos[0] if pos else None
    cwd=Path.cwd()
    if arg:
        p=Path(arg)
        if p.exists() and p.is_dir():
            raise AppError("Error when generating parser", cause="Path to a grammar file with `.js` or `.json` extension is required")
        if p.exists() and p.is_file():
            if p.suffix not in (".js",".json"):
                raise AppError("Error when generating parser", cause="Path to a grammar file with `.js` or `.json` extension is required")
            grammar_file=p
        elif not p.exists():
            if p.is_absolute():
                raise AppError("Error when generating parser", cause=f"Permission denied (os error 13) ({arg})")
            else:
                # treat as directory containing grammar.js (original joins)
                raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- No such file or directory (os error 2) ({arg}/grammar.js)")
        # grammar root determination
        if grammar_file.parent.name=="src": grammar_root=grammar_file.parent.parent
        else: grammar_root=grammar_file.parent if str(grammar_file.parent) else Path(".")
        if str(grammar_root)=="": grammar_root=Path(".")
    else:
        grammar_file=cwd/"grammar.js"; grammar_root=cwd
    # output dir
    output_arg=vals.get("output")
    if output_arg:
        out_path=Path(output_arg)
        if out_path.exists() and out_path.is_file():
            raise AppError("Error when generating parser", cause=f"File exists (os error 17) ({output_arg})")
        output_dir=out_path
    else:
        output_dir=grammar_root/"src"
    # tree-sitter.json
    ts_path=grammar_root/"tree-sitter.json"
    ts_data=None; version=None
    abi_given=vals.get("abi") or os.environ.get("TREE_SITTER_ABI_VERSION")
    if not ts_path.exists():
        warn("No `tree-sitter.json` file found in your grammar, this file is required to generate with ABI 15. Using ABI version 14 instead.\nThis file can be set up with `tree-sitter init`. For more information, see https://tree-sitter.github.io/tree-sitter/cli/init.")
        abi=14
    else:
        try:
            ts_data=parse_ts_config_file(ts_path)
        except Exception as e:
            raise AppError("Error when generating parser", cause=f"Failed to parse `{ts_path.resolve()}/tree-sitter.json` -- {e}" if False else f"Failed to parse `{(grammar_root.resolve()/ 'tree-sitter.json')}` -- {e}")
        version=ts_data.get("metadata",{}).get("version") if isinstance(ts_data.get("metadata"),dict) else None
        if abi_given:
            if abi_given=="latest": abi=15
            else:
                try: abi=int(abi_given)
                except:
                    pid=os.getpid()
                    raise PanicError("crates/cli/src/main.rs:940:41", f"invalid abi version flag: ParseIntError {{ kind: InvalidDigit }}")
                if abi<14 or abi>15:
                    raise AppError("Error when generating parser", cause=f"This version of Tree-sitter can only generate parsers with ABI version 14 - 15, not {abi}")
        else: abi=15
    grammar_obj=None; raw_json_text=None
    if grammar_file.suffix==".json":
        if not grammar_file.exists():
            raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- No such file or directory (os error 2) ({grammar_file})")
        raw_json_text=grammar_file.read_text(encoding="utf-8")
        try: grammar_obj=json.loads(raw_json_text)
        except json.JSONDecodeError as e:
            raise AppError("Error when generating parser", cause=serde_json_error(raw_json_text,e))
        # typed validation approximations
        if isinstance(grammar_obj,dict) and "name" in grammar_obj and not isinstance(grammar_obj["name"],str):
            # locate column approx
            raise AppError("Error when generating parser", cause=f"invalid type: integer `{grammar_obj['name']}`, expected a string at line 1 column 11")
    else:
        runtime=vals.get("js_runtime") or os.environ.get("TREE_SITTER_JS_RUNTIME") or "node"
        grammar_obj, _ = load_grammar_via_runtime(grammar_file, runtime, grammar_root)
    # validate grammar
    try:
        validate_grammar_for_generate(grammar_obj)
    except AppError:
        raise
    except Exception as e:
        raise AppError("Error when generating parser", cause=str(e))
    # create output
    try:
        output_dir.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        raise AppError("Error when generating parser", cause=f"{e.strerror} (os error {e.errno}) ({output_dir})")
    # write grammar.json
    if raw_json_text is not None:
        (output_dir/"grammar.json").write_text(raw_json_text, encoding="utf-8")
    else:
        (output_dir/"grammar.json").write_text(json.dumps(grammar_obj, indent=2, ensure_ascii=False), encoding="utf-8")
    # node types
    try:
        nt=generate_node_types(grammar_obj)
    except Exception as e:
        raise AppError("Error when generating parser", cause=str(e))
    (output_dir/"node-types.json").write_text(json.dumps(nt, indent=2, ensure_ascii=False), encoding="utf-8")
    if not vals.get("no_parser"):
        (output_dir/"tree_sitter").mkdir(parents=True, exist_ok=True)
        (output_dir/"tree_sitter"/"parser.h").write_bytes(resource_bytes("data/headers/parser.h"))
        (output_dir/"tree_sitter"/"alloc.h").write_bytes(resource_bytes("data/headers/alloc.h"))
        (output_dir/"tree_sitter"/"array.h").write_bytes(resource_bytes("data/headers/array.h"))
        pc=generate_parser_c(grammar_obj, abi=abi, version=version)
        (output_dir/"parser.c").write_text(pc, encoding="utf-8")
    if vals.get("log"):
        # simplistic debug log
        for name in (grammar_obj.get("rules",{}) or {}):
            pass
        sys.stderr.write("")
        # original prints various lines to stdout? It printed to stdout in probe (captured combined). We'll emit to stderr? Probe: captured via 2>&1. Assume stdout.
        for tok in collect_token_names(grammar_obj):
            print(f"error recovery - token {tok} has no conflicts")
        for tok in collect_token_names(grammar_obj):
            print(f"error recovery - include token {tok}")
    if vals.get("report_states_for_rule") is not None:
        print_report_states(grammar_obj, vals["report_states_for_rule"])
    if vals.get("build") or vals.get("debug_build"):
        if vals.get("build"): warn("--build is deprecated, use the `build` command")
        # build parser.so in grammar root
        bvals={"wasm":False,"output":None,"reuse_allocator":False,"debug":bool(vals.get("debug_build")),"verbose":False}
        cmd_build_internal(str(grammar_root), bvals)
    return 0

def collect_token_names(g):
    from .earley import CompiledGrammar
    cg=CompiledGrammar(g); names=[]
    for name in (g.get("rules",{}) or {}):
        if cg.is_token_rule(name) and not name.startswith("_"): names.append(name)
    return names

def print_report_states(g, rule):
    from .earley import CompiledGrammar
    cg=CompiledGrammar(g)
    aux=[]
    for name,expr in (g.get("rules",{}) or {}).items():
        # repeats
        def find(e):
            if isinstance(e,dict):
                if e.get("type") in ("REPEAT","REPEAT1"): aux.append(f"{name}_repeat1")
                if "content" in e: find(e["content"])
                for m in e.get("members",[]) or []: find(m)
        find(expr)
    entries=[]
    for a in aux: entries.append((a,2))
    for name in (g.get("rules",{}) or {}): entries.append((name,1))
    width=max(len(n) for n,_ in entries) if entries else 0
    for n,c in entries:
        print(f"{n:<{width}}\t{c}")
    if rule!="-" and rule in (g.get("rules",{}) or {}):
        print("")
        print("state index: 0")
        print("state id: 0")
        print(f"symbol sequence: {rule}")
        print("")
        print("items:")

def validate_grammar_for_generate(g):
    if not isinstance(g,dict): raise AppError("Error when generating parser", cause="Invalid grammar")
    rules=g.get("rules")
    if not rules: raise AppError("Error when generating parser", cause="Grammar must have at least one rule.")
    if not g.get("name"): raise AppError("Error when generating parser", cause="Grammar must have a name.")
    # declared precedences
    declared=set()
    for group in g.get("precedences",[]) or []:
        for e in group or []:
            if isinstance(e,dict) and e.get("type")=="STRING": declared.add(e.get("value"))
            if isinstance(e,dict) and e.get("type")=="SYMBOL": declared.add(e.get("name"))
    def walk(e, rule):
        if not isinstance(e,dict): return
        t=e.get("type")
        if t in ("PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC"):
            v=e.get("value")
            if isinstance(v,str) and declared and v not in declared:
                raise AppError("Error when generating parser", cause=f"Undeclared precedence '{v}' in rule '{rule}'")
            if isinstance(v,str) and not declared:
                raise AppError("Error when generating parser", cause=f"Undeclared precedence '{v}' in rule '{rule}'")
        if t=="SYMBOL":
            nm=e.get("name")
            # externals symbols are allowed if listed in externals as symbol names
            ext_names=set()
            for ex in g.get("externals",[]) or []:
                if isinstance(ex,dict) and ex.get("type")=="SYMBOL": ext_names.add(ex.get("name"))
            if nm not in rules and nm not in ext_names:
                # sym() can reference undefined; only error if rule is reachable? Original generates parser and may error for missing. But symtest with foo unused passed. So only check symbols in reachable rules from start.
                pass
        if "content" in e: walk(e["content"], rule)
        for m in e.get("members",[]) or []: walk(m, rule)
    for rn,expr in rules.items(): walk(expr, rn)
    # reachable undefined check
    start=next(iter(rules))
    seen=set(); stack=[start]
    while stack:
        rn=stack.pop()
        if rn in seen: continue
        seen.add(rn)
        # collect symbols
        syms=[]
        def collect(e):
            if isinstance(e,dict):
                if e.get("type")=="SYMBOL": syms.append(e.get("name"))
                if "content" in e: collect(e["content"])
                for m in e.get("members",[]) or []: collect(m)
        collect(rules.get(rn,{}))
        for s in syms:
            if s in rules and s not in seen: stack.append(s)
            elif s not in rules:
                ext_names={ex.get("name") for ex in g.get("externals",[]) or [] if isinstance(ex,dict) and ex.get("type")=="SYMBOL"}
