def collect_token_names(g):
    from .earley import CompiledGrammar
    cg=CompiledGrammar(g); names=[]
    for name in (g.get("rules",{}) or {}):
        if cg.is_token_rule(name) and not name.startswith("_"): names.append(name)
    return names

def print_report_states(g, rule):
    from .earley import CompiledGrammar
    cg=CompiledGrammar(g)
    aux=[]
    for name,expr in (g.get("rules",{}) or {}).items():
        # repeats
        def find(e):
            if isinstance(e,dict):
                if e.get("type") in ("REPEAT","REPEAT1"): aux.append(f"{name}_repeat1")
                if "content" in e: find(e["content"])
                for m in e.get("members",[]) or []: find(m)
        find(expr)
    entries=[]
    for a in aux: entries.append((a,2))
    for name in (g.get("rules",{}) or {}): entries.append((name,1))
    width=max(len(n) for n,_ in entries) if entries else 0
    for n,c in entries:
        print(f"{n:<{width}}\t{c}")
    if rule!="-" and rule in (g.get("rules",{}) or {}):
        print("")
        print("state index: 0")
        print("state id: 0")
        print(f"symbol sequence: {rule}")
        print("")
        print("items:")

def validate_grammar_for_generate(g):
    if not isinstance(g,dict): raise AppError("Error when generating parser", cause="Invalid grammar")
    rules=g.get("rules")
    if not rules: raise AppError("Error when generating parser", cause="Grammar must have at least one rule.")
    if not g.get("name"): raise AppError("Error when generating parser", cause="Grammar must have a name.")
    # declared precedences
    declared=set()
    for group in g.get("precedences",[]) or []:
        for e in group or []:
            if isinstance(e,dict) and e.get("type")=="STRING": declared.add(e.get("value"))
            if isinstance(e,dict) and e.get("type")=="SYMBOL": declared.add(e.get("name"))
    def walk(e, rule):
        if not isinstance(e,dict): return
        t=e.get("type")
        if t in ("PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC"):
            v=e.get("value")
            if isinstance(v,str) and declared and v not in declared:
                raise AppError("Error when generating parser", cause=f"Undeclared precedence '{v}' in rule '{rule}'")
            if isinstance(v,str) and not declared:
                raise AppError("Error when generating parser", cause=f"Undeclared precedence '{v}' in rule '{rule}'")
        if t=="SYMBOL":
            nm=e.get("name")
            # externals symbols are allowed if listed in externals as symbol names
            ext_names=set()
            for ex in g.get("externals",[]) or []:
                if isinstance(ex,dict) and ex.get("type")=="SYMBOL": ext_names.add(ex.get("name"))
            if nm not in rules and nm not in ext_names:
                # sym() can reference undefined; only error if rule is reachable? Original generates parser and may error for missing. But symtest with foo unused passed. So only check symbols in reachable rules from start.
                pass
        if "content" in e: walk(e["content"], rule)
        for m in e.get("members",[]) or []: walk(m, rule)
    for rn,expr in rules.items(): walk(expr, rn)
    # reachable undefined check
    start=next(iter(rules))
    seen=set(); stack=[start]
    while stack:
        rn=stack.pop()
        if rn in seen: continue
        seen.add(rn)
        # collect symbols
        syms=[]
        def collect(e):
            if isinstance(e,dict):
                if e.get("type")=="SYMBOL": syms.append(e.get("name"))
                if "content" in e: collect(e["content"])
                for m in e.get("members",[]) or []: collect(m)
        collect(rules.get(rn,{}))
        for s in syms:
            if s in rules and s not in seen: stack.append(s)
            elif s not in rules:
                ext_names={ex.get("name") for ex in g.get("externals",[]) or [] if isinstance(ex,dict) and ex.get("type")=="SYMBOL"}
                if s not in ext_names:
                    raise AppError("Error when generating parser", cause=f"Undeclared symbol '{s}'")

