def cmd_build_internal(grammar_dir_str, vals):
    gd=Path(grammar_dir_str) if grammar_dir_str else Path.cwd()
    # Resolve grammar dir absolute for compiler paths as original does (?) If path given relative, original keeps relative? Probe shows cwd case absolute. Use absolute if gd == cwd path "." else gd as given converted to Path absolute? We'll use gd.resolve() for compiler -I and sources to mimic cwd case.
    gd_abs=gd.resolve() if gd.exists() or True else gd
    gj=gd_abs/"src"/"grammar.json"
    if not gj.exists():
        raise AppError("Failed to compile parser", cause=f"No such file or directory (os error 2) ({gj})")
    try: gname=json.loads(gj.read_text()).get("name","")
    except Exception as e:
        raise AppError("Failed to compile parser", cause=str(e))
    if vals.get("wasm"):
        url="https://github.com/WebAssembly/wasi-sdk/releases/download/wasi-sdk-29/wasi-sdk-29.0-x86_64-linux.tar.gz"
        eprint(f"Downloading clang from {url}...")
        # attempt curl if available to mimic failure in offline env; if curl succeeds (online) we still can't easily build wasm - just fail
        raise AppError(f"Failed to download clang from {url}")
    output_arg=vals.get("output")
    if output_arg: out_path=Path(output_arg)
    else: out_path=gd_abs/"parser.so"
    # Create output parent
    try:
        if out_path.parent and str(out_path.parent): out_path.parent.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        raise AppError("Failed to create output path", cause=f"Permission denied (os error 13)")
    src_dir=gd_abs/"src"
    parser_c=src_dir/"parser.c"
    sources=[str(parser_c)]
    scanner_c=src_dir/"scanner.c"
    if scanner_c.exists(): sources.append(str(scanner_c))
    cc=os.environ.get("CC","cc")
    args=[]
    if vals.get("debug"):
        args+=[cc,"-O0","-ffunction-sections","-fdata-sections","-fPIC","-g","-gdwarf-4","-fno-omit-frame-pointer","-m64","-std=c11","-I",str(src_dir),"-Wall","-Wextra"]
        if vals.get("reuse_allocator"): args+=["-DTREE_SITTER_REUSE_ALLOCATOR"]
        args+=["-DTREE_SITTER_DEBUG","-Werror=implicit-function-declaration","-shared","-Wl,--no-undefined"]
    else:
        args+=[cc,"-O2","-ffunction-sections","-fdata-sections","-fPIC","-m64","-std=c11","-I",str(src_dir),"-Wall"]
        if vals.get("reuse_allocator"): args+=["-DTREE_SITTER_REUSE_ALLOCATOR"]
        args+=["-Werror=implicit-function-declaration","-shared","-Wl,--no-undefined"]
    args+=sources+["-o",str(out_path)]
    if vals.get("verbose"):
        sys.stderr.write("[] "+" ".join(args)+"\n\nLC_ALL=C\n")
    env=dict(os.environ); env["LC_ALL"]="C"
    try:
        proc=subprocess.run(args, capture_output=True, text=True, env=env)
    except FileNotFoundError:
        quoted=" ".join(f'"{a}"' for a in args)
        cause=f'Failed to execute the C compiler with the following command:\nLC_ALL="C" {quoted}\nError: No such file or directory (os error 2)'
        raise AppError("Failed to compile parser", cause=cause)
    if proc.returncode!=0:
        cause=f"Parser compilation failed.\nStdout: {proc.stdout}\nStderr: {proc.stderr}"
        raise AppError("Failed to compile parser", cause=cause.rstrip("\n") if proc.stderr else cause)
    return 0

