        pass
    if target is None:
        wprint(f"Current version: {cur}")
        return 0
    # validate target semver manually (positional already)
    eprint(f"Bumping version {cur} to {target}")
    errors=[]
    base=Path(grammar_dir).resolve()
    # update tree-sitter.json by replacing version value only
    new_text=re.sub(r'("version"\s*:\s*")'+re.escape(cur)+r'(")', r'\g<1>'+target+r'\g<2>', text, count=1)
    # In metadata only: first occurrence could be elsewhere; tree-sitter.json version appears in metadata; if multiple, search metadata section - use last? Original uses parsed update and re-serialize?? observed preserves formatting, so use occurrence after "metadata"
    if new_text==text:
        # try any version string
        new_text=re.sub(r'("version"\s*:\s*")[^"]*(")', r'\g<1>'+target+r'\g<2>', text, count=1)
    try:
        path.write_text(new_text, encoding="utf-8")
    except OSError as ex:
        errors.append((path, f"{ex.strerror} (os error {ex.errno})"))
    gd=base
    replace_version_in_file(gd/"Makefile", cur, target, r'VERSION := {old}', errors, mandatory=True)
    replace_version_in_file(gd/"CMakeLists.txt", cur, target, r'VERSION "{old}"', errors, mandatory=False)
    replace_version_in_file(gd/"Cargo.toml", cur, target, r'version = "{old}"', errors, mandatory=False)
    replace_version_in_file(gd/"package.json", cur, target, r'"version": "{old}"', errors, mandatory=False)
    replace_version_in_file(gd/"pyproject.toml", cur, target, r'version = "{old}"', errors, mandatory=False)
    replace_version_in_file(gd/"build.zig.zon", cur, target, r'\.version = "{old}"', errors, mandatory=False)
    if errors:
        body=""
        for p,msg in errors:
            body+=f"Failed to update {p}:\n{msg}\n\n"
        raise AppError("Failed to update one or more files:", body=body)
    return 0

