def load_grammar_via_runtime(grammar_file, runtime, grammar_dir):
    if runtime=="native":
        if not grammar_file.exists():
            raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- No such file or directory (os error 2) ({grammar_file})")
        try: text=grammar_file.read_text(encoding="utf-8")
        except OSError as e: raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- {e.strerror} (os error {e.errno}) ({grammar_file})")
        try:
            return load_grammar_js(text), None
        except JSError as e:
            cause=f"Failed to load grammar.js -- QuickJS error: Message: {e.message}\nStack:     at grammar.js:1:1\n\nType: {e.typ}"
            raise AppError("Error when generating parser", cause=cause)
        except Exception as e:
            # Python-level js parse errors that are tokenize/parser JSError already handled; syntax errors from parser raise JSError
            raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- QuickJS error: Message: {e}\nStack:     at grammar.js:1:1\n\nType: SyntaxError")
    # external runtime
    exe=shutil.which(runtime) if "/" not in runtime else runtime
    if not exe or not Path(exe).exists():
        raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- Failed to run `{runtime}` -- No such file or directory (os error 2)")
    env=dict(os.environ); env["TREE_SITTER_GRAMMAR_PATH"]=str(Path(grammar_file).resolve() if grammar_file.exists() else grammar_file.absolute())
    try:
        proc=subprocess.run([runtime], input=OUR_JS_LOADER, text=True, capture_output=True, env=env)
    except FileNotFoundError:
        raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- Failed to run `{runtime}` -- No such file or directory (os error 2)")
    if proc.returncode!=0:
        raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- `{runtime}` process exited with status {proc.returncode}")
    try:
        return json.loads(proc.stdout), None
    except Exception as e:
        raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- {proc.stdout[:200]}")

def cmd_generate(vals, pos):
    if vals.get("json") and not vals.get("json_summary"):
        warn("--json is deprecated, use --json-summary instead")
    arg=pos[0] if pos else None
    cwd=Path.cwd()
    if arg:
        p=Path(arg)
        if p.exists() and p.is_dir():
            raise AppError("Error when generating parser", cause="Path to a grammar file with `.js` or `.json` extension is required")
        if p.exists() and p.is_file():
            if p.suffix not in (".js",".json"):
                raise AppError("Error when generating parser", cause="Path to a grammar file with `.js` or `.json` extension is required")
            grammar_file=p
        elif not p.exists():
            if p.is_absolute():
                raise AppError("Error when generating parser", cause=f"Permission denied (os error 13) ({arg})")
            else:
                # treat as directory containing grammar.js (original joins)
                raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- No such file or directory (os error 2) ({arg}/grammar.js)")
        # grammar root determination
        if grammar_file.parent.name=="src": grammar_root=grammar_file.parent.parent
        else: grammar_root=grammar_file.parent if str(grammar_file.parent) else Path(".")
        if str(grammar_root)=="": grammar_root=Path(".")
    else:
        grammar_file=cwd/"grammar.js"; grammar_root=cwd
    # output dir
    output_arg=vals.get("output")
    if output_arg:
        out_path=Path(output_arg)
        if out_path.exists() and out_path.is_file():
            raise AppError("Error when generating parser", cause=f"File exists (os error 17) ({output_arg})")
        output_dir=out_path
    else:
        output_dir=grammar_root/"src"
    # tree-sitter.json
    ts_path=grammar_root/"tree-sitter.json"
    ts_data=None; version=None
    abi_given=vals.get("abi") or os.environ.get("TREE_SITTER_ABI_VERSION")
    if not ts_path.exists():
        warn("No `tree-sitter.json` file found in your grammar, this file is required to generate with ABI 15. Using ABI version 14 instead.\nThis file can be set up with `tree-sitter init`. For more information, see https://tree-sitter.github.io/tree-sitter/cli/init.")
