            raise AppError("Error when generating parser", cause=f"Failed to parse `{ts_path.resolve()}/tree-sitter.json` -- {e}" if False else f"Failed to parse `{(grammar_root.resolve()/ 'tree-sitter.json')}` -- {e}")
        version=ts_data.get("metadata",{}).get("version") if isinstance(ts_data.get("metadata"),dict) else None
        if abi_given:
            if abi_given=="latest": abi=15
            else:
                try: abi=int(abi_given)
                except:
                    pid=os.getpid()
                    raise PanicError("crates/cli/src/main.rs:940:41", f"invalid abi version flag: ParseIntError {{ kind: InvalidDigit }}")
                if abi<14 or abi>15:
                    raise AppError("Error when generating parser", cause=f"This version of Tree-sitter can only generate parsers with ABI version 14 - 15, not {abi}")
        else: abi=15
    grammar_obj=None; raw_json_text=None
    if grammar_file.suffix==".json":
        if not grammar_file.exists():
            raise AppError("Error when generating parser", cause=f"Failed to load grammar.js -- No such file or directory (os error 2) ({grammar_file})")
        raw_json_text=grammar_file.read_text(encoding="utf-8")
        try: grammar_obj=json.loads(raw_json_text)
        except json.JSONDecodeError as e:
            raise AppError("Error when generating parser", cause=serde_json_error(raw_json_text,e))
        # typed validation approximations
        if isinstance(grammar_obj,dict) and "name" in grammar_obj and not isinstance(grammar_obj["name"],str):
            # locate column approx
            raise AppError("Error when generating parser", cause=f"invalid type: integer `{grammar_obj['name']}`, expected a string at line 1 column 11")
    else:
        runtime=vals.get("js_runtime") or os.environ.get("TREE_SITTER_JS_RUNTIME") or "node"
        grammar_obj, _ = load_grammar_via_runtime(grammar_file, runtime, grammar_root)
    # validate grammar
    try:
        validate_grammar_for_generate(grammar_obj)
    except AppError:
        raise
    except Exception as e:
        raise AppError("Error when generating parser", cause=str(e))
    # create output
    try:
        output_dir.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        raise AppError("Error when generating parser", cause=f"{e.strerror} (os error {e.errno}) ({output_dir})")
    # write grammar.json
    if raw_json_text is not None:
        (output_dir/"grammar.json").write_text(raw_json_text, encoding="utf-8")
    else:
        (output_dir/"grammar.json").write_text(json.dumps(grammar_obj, indent=2, ensure_ascii=False), encoding="utf-8")
    # node types
    try:
        nt=generate_node_types(grammar_obj)
    except Exception as e:
        raise AppError("Error when generating parser", cause=str(e))
    (output_dir/"node-types.json").write_text(json.dumps(nt, indent=2, ensure_ascii=False), encoding="utf-8")
    if not vals.get("no_parser"):
        (output_dir/"tree_sitter").mkdir(parents=True, exist_ok=True)
        (output_dir/"tree_sitter"/"parser.h").write_bytes(resource_bytes("data/headers/parser.h"))
