# ---------- corpus tests ----------
class CorpusTest:
    def __init__(self, name, attrs, input_text, expected_text, group, filepath, raw_lines=None, expected_start=None, divider_index=None, header_end=None):
        self.name=name; self.attrs=attrs; self.input=input_text; self.expected=expected_text; self.group=group; self.filepath=filepath
        self.raw_lines=raw_lines; self.expected_start=expected_start; self.divider_index=divider_index

def parse_corpus_file(path):
    text=Path(path).read_text(encoding="utf-8", errors="replace")
    lines=text.splitlines(True)  # keep endings for update reconstruction
    tests=[]; i=0
    group=Path(path).stem
    # group for subdirectories relative to corpus ancestor unknown here; caller may adjust
    while i<len(lines):
        if re.match(r'^={3,}\s*\n?$', lines[i].rstrip("\n")):
            start=i; i+=1; header_lines=[]
            while i<len(lines) and not re.match(r'^={3,}\s*$', lines[i].strip()):
                header_lines.append(lines[i].strip()); i+=1
            if i>=len(lines): break
            i+=1  # closing ===
            header_nonempty=[h for h in header_lines if h!=""]
            name=header_nonempty[0] if header_nonempty else ""
            attrs=[h for h in header_nonempty[1:] if h.startswith(":")]
            input_lines=[]
            while i<len(lines) and not re.match(r'^-{3,}\s*$', lines[i].strip()):
                input_lines.append(lines[i]); i+=1
            divider=i; i+=1 if i<len(lines) else 0
            expected_lines=[]
            expected_start=i
            while i<len(lines) and not re.match(r'^={3,}\s*$', lines[i].strip()):
                expected_lines.append(lines[i]); i+=1
            tests.append(CorpusTest(name, attrs, "".join(input_lines), "".join(expected_lines), group, Path(path), lines, expected_start, divider))
        else:
            i+=1
    return tests

def find_corpus_tests(grammar_dir):
    base=Path(grammar_dir)/"test"/"corpus"
    tests=[]
    if not base.is_dir(): return tests
    files=sorted([p for p in base.rglob("*") if p.is_file()], key=lambda p: str(p.relative_to(base)))
    for f in files:
        ts=parse_corpus_file(f)
        rel=f.relative_to(base)
        group=str(rel.with_suffix("")) if len(rel.parts)>1 else f.stem
        for t in ts: t.group=group
        tests.extend(ts)
