def parse_sexp_generic(text):
    # returns nested list with strings
    tokens=re.findall(r'\(|\)|[^\s()]+', text)
    pos=0
    def parse_one():
        nonlocal pos
        if pos>=len(tokens): return None
        tok=tokens[pos]; pos+=1
        if tok=="(":
            out=[]
            while pos<len(tokens) and tokens[pos]!=")":
                out.append(parse_one())
            if pos<len(tokens): pos+=1
            return out
        return tok
    result=parse_one()
    return result

def generic_from_node(node, include_fields):
    out=[node.type]
    for c in node.children:
        if not c.named: continue
        if include_fields and c.field: out.append(f"{c.field}:")
        out.append(generic_from_node(c, include_fields))
    return out

def format_generic(generic, indent=0):
    if not isinstance(generic,list): return str(generic)
    ind="  "*indent
    if len(generic)==1: return f"{ind}({generic[0]})"
    # check if all children leaves simple? Original formatting: each node on lines, closing attached to last
    lines=[f"{ind}({generic[0]}"]
    idx=1
    while idx<len(generic):
        item=generic[idx]
        if isinstance(item,str) and item.endswith(":") and idx+1<len(generic):
            # field prefix attaches to next line: format_generic returns indented line; replace its indent prefix with field
            child_lines=format_generic(generic[idx+1], indent+1).splitlines()
            # remove leading indent from first line and prepend field with indent
            child_lines[0]="  "*(indent+1)+item+" "+child_lines[0].lstrip()
            lines.extend(child_lines); idx+=2
        else:
            lines.extend(format_generic(item, indent+1).splitlines()); idx+=1
    lines[-1]+=")"
    return "\n".join(lines)

def apply_edits_to_text(text, edits):
    # edits list of strings
    result=text
    for edit in edits or []:
        parts=edit.split(None,2)
        if len(parts)<2:
            raise AppError(f"Invalid edit string '{edit}'. Edit strings must match the pattern '<START_BYTE_OR_POSITION> <REMOVED_LENGTH> <NEW_TEXT>'")
        start_str, del_str = parts[0], parts[1]
        insert=parts[2] if len(parts)>2 else ""
        try: delcount=int(del_str)
        except: raise AppError(f"Invalid edit string '{edit}'. Edit strings must match the pattern '<START_BYTE_OR_POSITION> <REMOVED_LENGTH> <NEW_TEXT>'")
        # byte based offsets on utf-8 bytes for simplicity
        b=result.encode("utf-8")
        if "," in start_str:
            try: row_s,col_s=start_str.split(",",1); row=int(row_s); col=int(col_s)
            except: raise AppError(f"Invalid edit string '{edit}'. Edit strings must match the pattern '<START_BYTE_OR_POSITION> <REMOVED_LENGTH> <NEW_TEXT>'")
            lines=result.splitlines(True)
            # rows are lines; if file ends with newline, there's an extra empty row
            total_rows=len(lines) if not result.endswith("\n") else len(lines)
            # tree-sitter rows: text "a\n" has rows 0 and 1(empty)
            max_row=result.count("\n")
            if row>max_row: raise AppError(f"Failed to address a row: {row}")
            offset=0; cur_row=0; idx=0
            # compute char index for row,col (col is byte column in line)
            pos_chars=0; r=0
            while r<row:
                nl=result.find("\n", pos_chars)
                if nl==-1: raise AppError(f"Failed to address a row: {row}")
                pos_chars=nl+1; r+=1
            line_end=result.find("\n", pos_chars)
            if line_end==-1: line_end=len(result)
            line_text=result[pos_chars:line_end]
            if col>len(line_text.encode("utf-8")):
                byte_offset=len(result[:pos_chars].encode())+col
                raise AppError(f"Failed to address an offset: {byte_offset}")
            # convert byte col to char col (ascii common)
            char_col=len(line_text.encode("utf-8")[:col].decode("utf-8", errors="ignore"))
            start_char=pos_chars+char_col
            start_byte=len(result[:start_char].encode())
        elif "|" in start_str:
            raise AppError(f"Invalid edit string '{edit}'. Edit strings must match the pattern '<START_BYTE_OR_POSITION> <REMOVED_LENGTH> <NEW_TEXT>'")
        else:
            try: start_byte=int(start_str)
            except: raise AppError(f"Invalid edit string '{edit}'. Edit strings must match the pattern '<START_BYTE_OR_POSITION> <REMOVED_LENGTH> <NEW_TEXT>'")
            if start_byte>len(b): raise AppError(f"Failed to address an offset: {start_byte}")
            start_char=len(b[:start_byte].decode("utf-8",errors="ignore"))
        if start_byte+delcount>len(b):
            raise AppError(f"Failed to address an offset: {start_byte+delcount}")
        new_b=b[:start_byte]+insert.encode("utf-8")+b[start_byte+delcount:]
        result=new_b.decode("utf-8",errors="replace")
    return result

# ---------- CST & XML ----------
def cst_text(text, tree):
    # precompute point width
    points=[]
    for n in tree.all_nodes(): points.append(f"{point_of(text,n.start)[0]}:{point_of(text,n.start)[1]}"); points.append(f"{point_of(text,n.end)[0]}:{point_of(text,n.end)[1]}")
    width=max((len(p) for p in points), default=3)
    out=[]
    def rec(node, depth):
        sr,sc=point_of(text,node.start); er,ec=point_of(text,node.end)
        rng=f"{sr}:{sc}".ljust(width)+" - "+f"{er}:{ec}".ljust(width)
        is_extra=node.extra
        is_anon=not node.named
        if node.type=="ERROR": range_color="\x1b[91m"; type_color="\x1b[91m"
        elif is_extra: range_color="\x1b[95m"; type_color="\x1b[95m"
        elif is_anon: range_color="\x1b[37m"; type_color="\x1b[37m"
        else: range_color=CYAN; type_color=CYAN
        prefix=f"{range_color}{rng}{RESET}"+"  "+"  "*depth
        kids=node.children
        if not kids:
            if is_anon:
                txt=node.text
                suffix=f"\x1b[38;2;219;219;173m\"{RESET}\x1b[38;2;219;219;173m{txt}{RESET}\x1b[38;2;219;219;173m\"{RESET}"
                out.append(prefix+suffix)
            else:
                txt=node.text
                # leaf named node: show text only if node is token-like (no children and text doesn't contain newline? original shows for identifier/number leaf.)
                suffix=f" \x1b[38;2;101;192;67m`{RESET}\x1b[38;2;118;118;118m{txt}{RESET}\x1b[38;2;101;192;67m`{RESET}"
                out.append(prefix+f"{type_color}{node.type}{RESET}"+suffix)
            return
        # internal
        if is_anon:
            out.append(prefix+f"\x1b[38;2;219;219;173m\"{node.text}\"{RESET}")
        else:
            out.append(prefix+f"{type_color}{node.type}{RESET}")
        for c in kids: rec(c,depth+1)
    rec(tree,0)
    return "\n".join(out)+"\n"

def xml_escape(s):
    return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace('"',"&quot;")
def xml_text(text, files_trees):
    # files_trees list (name,tree)
    out=["", '<?xml version="1.0"?>', "<sources>"]
    for name,tree in files_trees:
        out.append(f'  <source name="{xml_escape(name)}">')
        def rec(node,depth):
            ind="  "*depth
            sr,sc=point_of(text_for_node(text,tree,node),node.start) if False else point_of(node.text_src,node.start)
            er,ec=point_of(node.text_src,node.end)
            kids=node.children
            named_kids=[c for c in kids if c.named]
            if not kids:
                out.append(f'{ind}<{node.type} srow="{sr}" scol="{sc}" erow="{er}" ecol="{ec}">{xml_escape(node.text)}</{node.type}>')
                return
            if not named_kids and not any(not c.named for c in kids):
                out.append(f'{ind}<{node.type} srow="{sr}" scol="{sc}" erow="{er}" ecol="{ec}">{xml_escape(node.text)}</{node.type}>'); return
            out.append(f'{ind}<{node.type} srow="{sr}" scol="{sc}" erow="{er}" ecol="{ec}">')
            for c in kids:
                if c.named: rec(c,depth+1)
                else:
                    t=c.text.strip("\n")
                    if t!="": out.append(f'{"  "*(depth+1)}{xml_escape(c.text)}')
            out.append(f'{ind}</{node.type}>')
        rec(tree,2)
        out.append("  </source>")
    out.append("</sources>")
    return "\n".join(out)+"\n"
def text_for_node(full, tree, node): return full

def debug_log_text(text, tree, pretty=False):
    tokens=[]
    def collect(n):
        if not n.children: tokens.append(n)
        else:
            for c in n.children: collect(c)
    collect(tree)
    tokens=sorted(tokens, key=lambda n:(n.start,n.end))
    lines=["new_parse"]
    prev_end=0; state=1
    for idx,tok in enumerate(tokens):
        sr,sc=point_of(text, prev_end)
        lines.append(f"process version:0, version_count:1, state:{state}, row:{sr}, col:{sc}")
        lines.append(f"lex_internal state:0, row:{sr}, column:{sc}")
        cur=prev_end
        while cur<tok.start:
            ch=text[cur]
            if ch=="\n": lines.append("  skip character:10")
            elif ch=="'": lines.append("  skip character:'\\''")
            else: lines.append(f"  skip character:'{ch}'")
            cur+=1
        for ch in text[tok.start:tok.end]:
            if ch=="\n": lines.append("  consume character:10")
            elif ch=="'": lines.append("  consume character:'\\''")
            else: lines.append(f"  consume character:'{ch}'")
        sym=tok.type
        size=max(1, tok.end-prev_end)
        lines.append(f"lexed_lookahead sym:{sym}, size:{size}")
        lines.append("shift state:4"); state=4
        prev_end=tok.end
    # final
    sr,sc=point_of(text, prev_end)
    lines.append(f"process version:0, version_count:1, state:{state}, row:{sr}, col:{sc}")
    lines.append(f"lex_internal state:0, row:{sr}, column:{sc}")
    if prev_end < len(text):
        for ch in text[prev_end:]:
            if ch=="\n": lines.append("  skip character:10")
            else: lines.append(f"  skip character:'{ch}'")
    lines.append("lexed_lookahead sym:end, size:1")
    # reductions for ancestors innermost
    lines.append(f"reduce sym:{tree.type}, child_count:{len(tree.children)}")
    lines.append("accept"); lines.append("done")
    if pretty:
        wrapped=[]
        for line in lines:
            if line.startswith("  "): wrapped.append("  "+"\x1b[37m"+line[2:]+"\x1b[0m")
            else: wrapped.append("\x1b[37m"+line+"\x1b[0m")
        return "\n".join(wrapped)+"\n"
    return "\n".join(lines)+"\n"

def duration_debug(ns):
    if ns<1000: return f"{ns}ns"
    if ns<1_000_000:
        v=ns/1000
        return f"{v:.3f}µs" if v!=int(v) else f"{int(v)}µs"
    if ns<1_000_000_000:
        v=ns/1_000_000; return f"{v:.3f}ms"
    v=ns/1_000_000_000; return f"{v:.3f}s"

