        is_extra=node.extra
        is_anon=not node.named
        if node.type=="ERROR": range_color="\x1b[91m"; type_color="\x1b[91m"
        elif is_extra: range_color="\x1b[95m"; type_color="\x1b[95m"
        elif is_anon: range_color="\x1b[37m"; type_color="\x1b[37m"
        else: range_color=CYAN; type_color=CYAN
