                suffix=f" \x1b[38;2;101;192;67m`{RESET}\x1b[38;2;118;118;118m{txt}{RESET}\x1b[38;2;101;192;67m`{RESET}"
                out.append(prefix+f"{type_color}{node.type}{RESET}"+suffix)
