def one_line_generic(g):
    if g is None: return ""
    if isinstance(g,list):
        return "("+" ".join(one_line_generic(x) if isinstance(x,list) else str(x) for x in g)+")"
    return str(g)

def rewrite_corpus_expected(test, updated_expected):
    path=Path(test.filepath)
    tests_in_file=parse_corpus_file(path)
    # find matching test by name and expected start proximity: use index among tests with same name? Simpler: reparse and locate nth occurrence of test name matching original test order in global tests list not known.
    # Use test.expected_start line index from original parse (valid if file not yet rewritten in this run for earlier tests; rewriting sequentially can shift lines but expected formats usually have same line counts? Our format may differ line counts, invalidating later offsets.)
    lines=Path(path).read_text(encoding="utf-8").splitlines(True)
    # Recalculate fresh parse to get current expected_start for test with same name and input
    fresh=parse_corpus_file(path)
    target=None
    for ft in fresh:
        if ft.name==test.name and ft.input==test.input: target=ft; break
    if target is None: return
    start=target.expected_start; end=start
    while end<len(lines) and not re.match(r'^={3,}\s*$', lines[end].strip()):
        end+=1
    new_lines=lines[:start]+[updated_expected]+lines[end:]
    Path(path).write_text("".join(new_lines), encoding="utf-8")

