        files=sorted([p for p in hdir.rglob("*") if p.is_file()], key=lambda p:str(p.relative_to(hdir)))
        if files:
            outputs.append("syntax highlighting:")
            for idx,f in enumerate(files,1):
                assertions, source = extract_assertions(f.read_text(encoding="utf-8",errors="replace"))
                passed=True; hl=[]
