def extract_assertions(text):
    lines=text.splitlines()
    source_lines=[]; assertions=[]
    # map from source line index (in source_lines) to original?
    for line in lines:
        stripped=line.lstrip()
        is_assert=False; cap=None; col=None; kind=None
        m=None
        # assertion pattern after comment prefix
        m=re.match(r'^(?:\s*)(?://|#|--|;|/\*|<!--)\s*(.*)$', line)
        if m:
            rest=m.group(1)
            # rest starts with spaces then ^, |, or <- 
            mm=re.match(r'^(\s*)(\^|\||<-|v)\s*(.+?)\s*$', rest)
            if mm:
                is_assert=True
                marker_col=line.find(mm.group(2))
                cap=mm.group(3).strip(); kind=mm.group(2); col=marker_col
        if is_assert and source_lines:
            target_row=len(source_lines)-1
            assertions.append({"row":target_row,"col":col,"capture":cap,"kind":kind})
        else:
            source_lines.append(line)
    return assertions, "\n".join(source_lines)+( "\n" if text.endswith("\n") else "")

