def assertion_passes_highlight(a, highlights, source):
    # highlights list of dicts with row/col byte ranges and capture
    lines=source.splitlines()
    if a["row"]>=len(lines): return False
    # target byte column
    target_col=a["col"]
    cap=a["capture"].lstrip("@")
    for h in highlights:
        if h["start_row"]==a["row"] and h["start_col"]<=target_col<h["end_col"] or (h["start_row"]==a["row"] and h["start_col"]==target_col):
            name=h["capture"]
            if name==cap or name.startswith(cap+"."): return True
        # also capture that starts at target and kind <-
        if a["kind"]=="<-" and h["start_row"]==a["row"] and h["start_col"]<=target_col:
            name=h["capture"]
            if name==cap or name.startswith(cap+"."): return True
    return False
def assertion_passes_tag(a, tags, source):
    cap=a["capture"].lstrip("@")
    for tg in tags:
        if tg["start_row"]==a["row"] and tg["start_col"]<=a["col"]<tg["end_col"]:
            full=f"{tg['role_full']}"  # definition.function etc
            if full==cap or tg["capture"]==cap: return True
    return False

# ---------- query helpers ----------
def capture_names_in_order(qtext):
    names=[]
    for m in re.finditer(r'@([A-Za-z0-9_\-\.]+)', qtext):
        n=m.group(1)
        if n not in names: names.append(n)
    return names

def parse_query_text(qtext, grammar):
    parser=QParser(qtext)
    patterns=parser.parse()
    validate_patterns(patterns, grammar, qtext)
    return patterns

def load_query_file(path):
    p=Path(path)
    if not p.exists():
        raise AppError(f"Error reading query file {path}", cause="No such file or directory (os error 2)")
    try: return p.read_text(encoding="utf-8")
    except OSError as e: raise AppError(f"Error reading query file {path}", cause=f"{e.strerror} (os error {e.errno})")

def query_error_app(e):
    if e.kind=="invalid_node":
        return AppError("Query compilation failed", cause=f"Query error at {e.line}:{e.col}. Invalid node type \"{e.msg.split('\\\"')[1] if '\\\"' in e.msg else ''}\"" if False else f"Query error at {e.line}:{e.col}. {e.msg}")
    if e.kind=="impossible":
        lt=e.line_text or ""
        caret=" "*(4+(e.caret_col-1))+"^" if e.caret_col else "^"
        return AppError("Query compilation failed", cause=f"Query error at {e.line}:{e.col}. Impossible pattern:\n{lt}\n{caret}")
    if e.kind=="invalid_field":
        return AppError("Query compilation failed", cause=f"Query error at {e.line}:{e.col}. {e.msg}")
    return AppError("Query compilation failed", cause=f"Query error at {e.line}:{e.col}. Invalid syntax:\n{e.msg}")

def format_capture(node, name, index, text, captures_mode=False, pattern_index=None):
    sr,sc=point_of(text,node.start); er,ec=point_of(text,node.end)
    txt=node.text
    if "\n" in txt:
        if captures_mode: return f"    pattern: {pattern_index:2}, capture: {name}, start: ({sr}, {sc}), end: ({er}, {ec})"
        return f"    capture: {name}, start: ({sr}, {sc}), end: ({er}, {ec})"
    if captures_mode:
        return f"    pattern: {pattern_index:2}, capture: {index} - {name}, start: ({sr}, {sc}), end: ({er}, {ec}), text: `{txt}`"
    return f"    capture: {index} - {name}, start: ({sr}, {sc}), end: ({er}, {ec}), text: `{txt}`"

def get_query_results(patterns, tree, capture_order, byte_range=None, row_range=None, containing_byte=None, containing_row=None, text=""):
    matches=execute_query(patterns, tree)
    filtered=[]
    for pat_idx,node,bindings in matches:
        # ranges applied to root node? tree-sitter query cursor ranges restrict nodes searched: matches whose root node intersects range
        if byte_range:
            s,e=byte_range
            if not (node.start<e and node.end>s if e>s else node.start>=s and node.end<=e): 
                if e>s and not (node.end>s and node.start<e): continue
        if containing_byte:
            s,e=containing_byte
            if not (node.start>=s and node.end<=e): continue
        if row_range:
            s,e=row_range
            sr=point_of(text,node.start)[0]; er=point_of(text,node.end)[0]
            if not (sr>=s and sr<=e): continue
        if containing_row:
            s,e=containing_row
            sr=point_of(text,node.start)[0]; er=point_of(text,node.end)[0]
            if not (sr>=s and er<=e): continue
        filtered.append((pat_idx,node,bindings))
    return filtered

def parse_range_arg(v):
    if v is None: return None
    parts=str(v).split(":")
    if len(parts)<2: raise AppError(f"Invalid range '{v}', expected 'start:end'")
    try: return (int(parts[0]), int(parts[1]))
    except: raise AppError(f"Invalid range '{v}', expected 'start:end'")

