def render_diff(expected_generic, actual_generic):
    exp_lines=format_generic(expected_generic,0).splitlines()
    act_lines=format_generic(actual_generic,0).splitlines()
    sm=difflib.SequenceMatcher(None, exp_lines, act_lines)
    out=[]  # (line,color)
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag=="equal":
            for l in act_lines[j1:j2]: out.append((l,None))
        elif tag=="delete":
            for l in exp_lines[i1:i2]: out.append((l,GREEN))
        elif tag=="insert":
            for l in act_lines[j1:j2]: out.append((l,RED))
        elif tag=="replace":
            for l in exp_lines[i1:i2]: out.append((l,GREEN))
            for l in act_lines[j1:j2]: out.append((l,RED))
    return out

