def tags_from_patterns(patterns, tree, text, capture_order):
    matches=execute_query(patterns, tree)
    tags=[]
    lines=text.splitlines()
    for pat_idx,node,bindings in matches:
        name_nodes=bindings.get("name",[])
        if not name_nodes: continue
        # find tag kind captures: keys definition.* / reference.*
        kinds=[]
        for k,v in bindings.items():
            if k.startswith("definition.") or k.startswith("reference."):
                role="def" if k.startswith("definition.") else "ref"
                kind=k.split(".",1)[1] if "." in k else ""
                kinds.append((k,kind,role,v))
        if not kinds:
            # pattern may have @definition... on root but no extra capture besides name? still skip
            continue
        for nn in name_nodes:
            for full,kind,role,_v in kinds:
                sr,sc=point_of(text,nn.start); er,ec=point_of(text,nn.end)
                line_text=lines[sr] if sr < len(lines) else ""
                tags.append({"name":nn.text,"kind":kind,"role":role,"role_full":full,"capture":full,"start_row":sr,"start_col":sc,"end_row":er,"end_col":ec,"start":nn.start,"end":nn.end,"line":line_text})
    tags.sort(key=lambda t:t["start"])
    return tags

