        # language in subdir of grammar dir
        lang=lang_from_grammar_dir(Path(grammar_dir)/vals["subdir"])
    tests=find_corpus_tests(grammar_dir)
    if vals.get("subdir"):
        tests=find_corpus_tests(Path(grammar_dir)/vals["subdir"])
    seed=random.getrandbits(64)
    wprint(f"Seed: {seed}")
    wprint("")
    include=vals.get("include") or []; exclude=vals.get("exclude") or []; skip=vals.get("skip") or []
    iterations=int(vals.get("iterations") or 10); max_edits=int(vals.get("edits") or 3)
    rng=random.Random(seed)
    idx=0
    for t in tests:
        if any(re.search(p,t.name) for p in exclude if True): continue
        if include and not any(re.search(p,t.name) for p in include): continue
        if t.name in skip: continue
        if any(a.startswith(":skip") for a in t.attrs): continue
        wprint(f"  {idx}. {lang.name} - corpus - {t.group} - {t.name}")
        idx+=1
        # perform fuzz edits
        for _ in range(iterations):
            txt=t.input
            for _e in range(max_edits):
                if not txt: break
                posn=rng.randrange(len(txt)+1); action=rng.randrange(3)
                if action==0 and posn<len(txt): txt=txt[:posn]+txt[posn+1:]
                elif action==1: txt=txt[:posn]+rng.choice("abcxyz123 @()") + txt[posn:]
                else:
                    if posn<len(txt): txt=txt[:posn]+rng.choice("abcxyz123")+txt[posn+1:]
            try: parse_text_with_lang(lang, txt)
            except Exception: pass
    return 0

