def ansi_for_style(style):
    if style is None: return None
    if isinstance(style,(int,float)):
        return f"\x1b[38;5;{int(style)}m"
    if isinstance(style,dict):
        codes=""
        if style.get("bold"): codes+="\x1b[1m"
        if style.get("italic"): codes+="\x1b[3m"
        if style.get("underline"): codes+="\x1b[4m"
        if "color" in style and style["color"] is not None: codes+=f"\x1b[38;5;{int(style['color'])}m"
        return codes if codes else None
    return None
def css_for_style(style):
    if style is None: return ""
    props=[]
    if isinstance(style,dict):
        if style.get("italic"): props.append("font-style: italic")
        if style.get("bold"): props.append("font-weight: bold")
        if style.get("underline"): props.append("text-decoration: underline")
        if "color" in style and style["color"] is not None: props.append(f"color: {xterm_hex(int(style['color']))}")
    elif isinstance(style,(int,float)):
        props.append(f"color: {xterm_hex(int(style))}")
    return ";".join(props)
def css_for_style_class(style):
