        return table[n]
    if n<232:
        idx=n-16; r=idx//36; g=(idx%36)//6; b=idx%6
        levels=[0,95,135,175,215,255]
        return f"#{levels[r]:02x}{levels[g]:02x}{levels[b]:02x}"
    v=8+10*(n-232); return f"#{v:02x}{v:02x}{v:02x}"

