def render_highlight_ansi(text, highlights, theme):
    # per character style, choose capture with smallest span that covers char, later in list wins for equal
    styles=[None]*len(text)
    # sort by span descending so smaller overwrite
    ordered=sorted(highlights, key=lambda h: (-(h["end"]-h["start"]), h["start"]))
    for h in ordered:
        style=theme_style_for_capture(theme, h["capture"])
        ansi=ansi_for_style(style)
        if ansi is None: continue
        for i in range(h["start"], min(h["end"], len(text))): styles[i]=ansi
    out=[]; cur=None; buf=""
    for i,ch in enumerate(text):
        st=styles[i]
        if st!=cur:
            if buf:
                out.append((f"{cur}{buf}{RESET}" if cur else buf)); buf=""
            cur=st
        buf+=ch
    if buf: out.append((f"{cur}{buf}{RESET}" if cur else buf))
    return "".join(out)

def render_highlight_html(text, highlights, theme, css_classes=False, config_theme=None):
    # build per line
    lines=text.splitlines(True)
    entries=[]
    # theme entries in insertion order from config theme if provided else default
    theme_dict=config_theme or theme
    for name,style in (theme_dict.items() if isinstance(theme_dict,dict) else []):
        if style is None: continue
        entries.append(f"    .{name} {{ {css_for_style_class(style)[:-1] if False else ''}{'font-style: italic;' if isinstance(style,dict) and style.get('italic') else ''}{'font-weight: bold;' if isinstance(style,dict) and style.get('bold') else ''}{'text-decoration: underline;' if isinstance(style,dict) and style.get('underline') else ''}color: {xterm_hex(int(style['color']) if isinstance(style,dict) else int(style))}; }}")
    # The generic loop above duplicates color formatting incorrectly for int styles; reconstruct properly:
    entries=[]
    for name,style in (theme_dict.items() if isinstance(theme_dict,dict) else []):
        if style is None: continue
        props=""
        if isinstance(style,dict):
            if style.get("italic"): props+="font-style: italic;"
            if style.get("bold"): props+="font-weight: bold;"
            if style.get("underline"): props+="text-decoration: underline;"
            if "color" in style and style["color"] is not None: props+=f"color: {xterm_hex(int(style['color']))};"
        else:
            props+=f"color: {xterm_hex(int(style))};"
        entries.append(f"    .{name} {{ {props} }}")
    head=["", "<!doctype HTML>", "<head>", "  <title>Tree-sitter Highlighting</title>", "  <style>", "    body {", "      font-family: monospace", "    }", "    .line-number {", "      user-select: none;", "      text-align: right;", "      color: rgba(27,31,35,.3);", "      padding: 0 10px;", "    }", "    .line {", "      white-space: pre;", "    }", "  </style>", "  <style>"]
    head.extend(entries)
    head+=["  </style>", "", "</head>", "<body>", "", "<table>"]
    rows=[]
    # compute styles per char same as ansi but capture name/style
    # For html, use capture->style mapping via class name or inline style
    # build spans per line
    hl_spans=[]
    ordered=sorted(highlights, key=lambda h: (-(h["end"]-h["start"]), h["start"]))
    char_capture=[None]*len(text)
    for h in ordered:
        if theme_style_for_capture(theme, h["capture"]) is None: continue
        for i in range(h["start"], min(h["end"], len(text))): char_capture[i]=h["capture"]
    pos=0
    for idx,line in enumerate(lines,1):
        line_text=line
        start=pos; end=pos+len(line_text); pos=end
        rendered=""; cur=None; buf=""
        def flush(buf,cur):
            if not buf: return ""
            esc=buf.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
            if cur is None: return esc
            if css_classes:
                # class name is longest prefix that exists in theme? original class is capture name itself (full). Use capture name.
                return f"<span class='{cur}'>{esc}</span>"
            else:
                style=theme_style_for_capture(theme, cur)
                css=css_for_style(style)
                return f"<span style='{css}'>{esc}</span>"
        for j,ch in enumerate(line_text):
            cap=char_capture[start+j] if start+j < len(char_capture) else None
            if cap!=cur:
                rendered+=flush(buf,cur); buf=""; cur=cap
            buf+=ch
        rendered+=flush(buf,cur)
        rows.append(f"<tr><td class=line-number>{idx}</td><td class=line>{rendered}</td></tr>")
    doc=head+rows+["</table>", "", "</body>", ""]
    return "\n".join(doc)+"\n"

