def interactive_init(grammar_dir):
    raw=RawTerminal(0) if sys.stdin.isatty() else None
    with (raw if raw else _nullcontext()):
        # initial prompts
        while True:
            name=prompt_text("Parser name", None, raw, validate_name=True)
            camel_default="".join(part[:1].upper()+part[1:] for part in name.split("_") if part)
            camel=prompt_text("CamelCase name", camel_default, raw)
            title=prompt_text("Title (human-readable name)", camel, raw)
            desc_default=f"{title} grammar for tree-sitter"
            # description default not shown in original prompt, pass None display but apply if empty: emulate by custom
            desc=prompt_text("Description", None, raw)
            if desc=="": desc=desc_default
            repo_default=f"https://github.com/tree-sitter/tree-sitter-{name}"
            repo=prompt_text("Repository URL", None, raw)
            if repo=="": repo=repo_default
            funding=prompt_text("Funding URL", None, raw)
            scope=prompt_text("TextMate scope", f"source.{name}", raw)
            file_types_s=prompt_text("File types (space-separated)", name, raw)
            version=prompt_text("Version", "0.1.0", raw)
            license_=prompt_text("License", "MIT", raw)
            author=prompt_text("Author name", None, raw)
            email=prompt_text("Author email", None, raw)
            url=prompt_text("Author URL", None, raw)
            namespace=prompt_text("Package namespace", "io.github.tree-sitter", raw)
            bindings=prompt_bindings(raw)
            cfg={"name":name,"camelcase":camel,"title":title,"description":desc,"repository":repo,"funding":funding,"scope":scope,"file_types":file_types_s.split() if file_types_s else [],"version":version,"license":license_,"author":author,"email":email,"url":url,"namespace":namespace,"bindings":bindings}
            while True:
                print_init_config(cfg)
                if prompt_confirm(raw): break
                field=prompt_select_field(raw)
                if field=="exit": return 0
                if field=="bindings": cfg["bindings"]=prompt_bindings(raw)
                elif field=="file_types":
                    v=prompt_text("File types (space-separated)", " ".join(cfg["file_types"]), raw); cfg["file_types"]=v.split()
                else:
                    label_map={"name":"Parser name","camelcase":"CamelCase name","title":"Title (human-readable name)","description":"Description","repository":"Repository URL","funding":"Funding URL","scope":"TextMate scope","version":"Version","license":"License","author":"Author name","email":"Author email","url":"Author URL","namespace":"Package namespace"}
                    v=prompt_text(label_map.get(field,field), str(cfg[field]), raw); cfg[field]=v
            break
    write_init_files(grammar_dir, cfg, overwrite=True)
    return 0

