def cmd_init(vals,pos):
    grammar_dir=vals.get("grammar_path") or "."
    gd=Path(grammar_dir)
    if (gd/"tree-sitter.json").exists():
        cfg=cfg_from_existing(gd)
        if vals.get("update"):
            # rewrite python __init__.py if present / python binding
            files=init_template_files(cfg)
            # original always says Replacing __init__.py in our earlier repo (python true). If py binding enabled, mimic.
            if cfg["bindings"].get("python"):
                # find python init rel
                for rel,content in files.items():
                    if rel.endswith("__init__.py"):
                        p=gd/rel; p.parent.mkdir(parents=True, exist_ok=True); p.write_text(content)
                        wprint("Replacing __init__.py")
                        break
            write_init_files(gd, cfg, overwrite=False, only_missing=True)
        else:
            write_init_files(gd, cfg, overwrite=False, only_missing=True)
