class RawTerminal:
    def __init__(self, fd=0):
        self.fd=fd; self.old=None
    def __enter__(self):
        try:
            import termios, tty
            self.old=termios.tcgetattr(self.fd); tty.setraw(self.fd)
        except Exception: self.old=None
        return self
    def __exit__(self, *args):
        if self.old:
            import termios; termios.tcsetattr(self.fd, termios.TCSADRAIN, self.old)
    def read_key(self):
        ch=os.read(self.fd,1)
        if not ch: return ""
        if ch==b"\x1b":
            seq=os.read(self.fd,2)
            if seq==b"[A": return "UP"
            if seq==b"[B": return "DOWN"
            return "ESC"
        return ch.decode(errors="replace")

