def main(argv=None):
    if argv is None: argv=sys.argv[1:]
    args=list(argv)
    try:
        if not args:
            sys.stderr.write(help_text(None)); return 2
        first=args[0]
        if first in ("-h","--help"):
            sys.stdout.write(help_text(None)); return 0
        if first in ("-V","--version"):
            wprint(f"tree-sitter {VERSION}"); return 0
        if first.startswith("-"):
            # unknown top-level argument
            tok=first.split("=")[0]
            sims=did_you_mean(tok.lstrip("-"), ["help","version"])
            msg=f"error: unexpected argument '{tok}' found\n"
            if sims: msg+=f"\n  tip: a similar argument exists: '--{sims[-1]}'\n"
            msg+=f"\nUsage: {bin_name()} <COMMAND>\n\nFor more information, try '--help'.\n"
            sys.stderr.write(msg); return 2
        cmd=ALIASES.get(first)
        if cmd is None:
            sims=did_you_mean(first, SUBCOMMAND_CANDIDATES)
            msg=f"error: unrecognized subcommand '{first}'\n"
            if sims:
                if len(sims)==1: msg+=f"\n  tip: a similar subcommand exists: '{sims[0]}'\n"
                else: msg+="\n  tip: some similar subcommands exist: "+", ".join(f"'{s}'" for s in sims)+"\n"
            msg+=f"\nUsage: {bin_name()} <COMMAND>\n\nFor more information, try '--help'.\n"
            sys.stderr.write(msg); return 2
        spec=SPECS[cmd]
        vals,pos=parse_cmd_args(spec, args[1:])
        # conflicts
        if cmd=="version" and vals.get("bump") and pos:
            msg=f"error: the argument '[VERSION]' cannot be used with '--bump <BUMP>'\n\nUsage: {bin_name()} version <VERSION>\n\nFor more information, try '--help'.\n"
            sys.stderr.write(msg); return 2
        # dispatch
        if cmd=="init-config": return cmd_init_config(vals,pos)
        if cmd=="dump-languages": return cmd_dump_languages(vals,pos)
        if cmd=="version": return cmd_version(vals,pos)
        if cmd=="generate": return cmd_generate(vals,pos)
        if cmd=="build": return cmd_build(vals,pos)
        if cmd=="parse": return cmd_parse(vals,pos)
        if cmd=="test": return cmd_test(vals,pos)
        if cmd=="query": return cmd_query(vals,pos)
        if cmd=="highlight": return cmd_highlight(vals,pos)
        if cmd=="tags": return cmd_tags(vals,pos)
        if cmd=="fuzz": return cmd_fuzz(vals,pos)
        if cmd=="playground": return cmd_playground(vals,pos)
        if cmd=="complete": return cmd_complete(vals,pos)
        if cmd=="init": return cmd_init(vals,pos)
        return 0
    except HelpDisplayed:
        return 0
    except ClapError as e:
        sys.stderr.write(str(e)); return 2
    except PanicError as e:
        pid=os.getpid(); sys.stderr.write(f"\nthread 'main' ({pid}) panicked at {e.location}:\n{e.message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"); return 101
    except AppError as e:
        sys.stderr.write(format_error(e)); return 1
    except BrokenPipeError:
        try: sys.stdout.close()
        except: pass
        return 0
    except KeyboardInterrupt:
        return 130

if __name__=="__main__":
