def init_template_files(cfg, overwrite=False):
    # cfg is config dict for substitutions
    manifest=resource_text("data/init_manifest.txt").splitlines()
    name=cfg["name"]; camel=cfg["camelcase"]
    subs={"{{NAME}}":name,"{{NAME_DASH}}":name.replace("_","-"),"{{CAMEL}}":camel,"{{DESCRIPTION}}":cfg["description"],"{{REPOSITORY}}":cfg["repository"],"{{FUNDING}}":cfg.get("funding",""),"{{SCOPE}}":cfg["scope"],"{{VERSION}}":cfg["version"],"{{LICENSE}}":cfg["license"],"{{AUTHOR}}":cfg["author"],"{{EMAIL}}":cfg["email"],"{{URL}}":cfg["url"],"{{NAMESPACE}}":cfg["namespace"],"{{TITLE}}":cfg["title"]}
    def sub_text(s):
        for k,v in subs.items(): s=s.replace(k,v)
        return s
    bindings=cfg["bindings"]
    def include(rel):
        if rel in (".editorconfig",".gitattributes",".gitignore","grammar.js"): return True
        if rel.startswith("bindings/c/") or rel in ("CMakeLists.txt","Makefile"): return bindings.get("c")
        if rel.startswith("bindings/go/") or rel=="go.mod": return bindings.get("go")
        if rel.startswith("bindings/node/") or rel in ("binding.gyp","package.json"): return bindings.get("node")
        if rel.startswith("bindings/python/") or rel in ("pyproject.toml","setup.py"): return bindings.get("python")
        if rel.startswith("bindings/rust/") or rel=="Cargo.toml": return bindings.get("rust")
        if rel.startswith("bindings/swift/") or rel=="Package.swift": return bindings.get("swift")
        return True
    files={}
    for rel in manifest:
        if not include(rel): continue
        templ=resource_text("data/init/"+rel)
        content=sub_text(templ)
        out_rel=sub_text(rel)
        files[out_rel]=content
    # tree-sitter.json generated
    ts={
      "$schema":"https://tree-sitter.github.io/tree-sitter/assets/schemas/config.schema.json",
      "grammars":[{"name":name,"camelcase":camel,"title":cfg["title"],"scope":cfg["scope"],"file-types":cfg["file_types"],"injection-regex":f"^{name}$","class-name":f"TreeSitter{camel}"}],
      "metadata":{"version":cfg["version"],"license":cfg["license"],"description":cfg["description"],"authors":[{"name":cfg["author"],"email":cfg["email"],"url":cfg["url"]}],"links":{"repository":cfg["repository"],"funding":cfg.get("funding","")}},
      "bindings":{k:bool(bindings.get(k)) for k in ["c","go","java","node","python","rust","swift","zig"]}
    }
    files["tree-sitter.json"]=json.dumps(ts, indent=2)
    # java / zig plausible files if selected
    if bindings.get("java"):
        ns=cfg["namespace"]
        files["pom.xml"]=f"<project><modelVersion>4.0.0</modelVersion><groupId>{ns}</groupId><artifactId>tree-sitter-{name.replace('_','-')}</artifactId><version>{cfg['version']}</version></project>\n"
        java_dir=f"bindings/java/{ns.replace('.','/').replace('-','_')}"
        files[f"{java_dir}/TreeSitter{camel}.java"]=f"package {ns};\n\npublic class TreeSitter{camel} {{\n}}\n"
    if bindings.get("zig"):
        files["build.zig"]="const std = @import(\"std\");\n\npub fn build(b: *std.Build) void {}\n"
        files["build.zig.zon"]=f".{{\n    .name = \"tree-sitter-{name.replace('_','-')}\",\n    .version = \"{cfg['version']}\",\n}}\n"
        files["bindings/zig/root.zig"]="// Zig bindings\n"
    return files

def write_init_files(base_dir, cfg, overwrite=False, only_missing=False):
