class RawTerminal:
    def __init__(self, fd=0):
        self.fd=fd; self.old=None
    def __enter__(self):
        try:
            import termios, tty
            self.old=termios.tcgetattr(self.fd); tty.setraw(self.fd)
        except Exception: self.old=None
        return self
    def __exit__(self, *args):
        if self.old:
            import termios; termios.tcsetattr(self.fd, termios.TCSADRAIN, self.old)
    def read_key(self):
        ch=os.read(self.fd,1)
        if not ch: return ""
        if ch==b"\x1b":
            seq=os.read(self.fd,2)
            if seq==b"[A": return "UP"
            if seq==b"[B": return "DOWN"
            return "ESC"
        return ch.decode(errors="replace")

def prompt_text(label, default=None, rawterm=None, validate_name=False):
    while True:
        defpart=f" \x1b[38;5;8m({default})\x1b[0m" if default is not None and default!="" else ""
        sys.stdout.write(f"\x1b[33m?\x1b[0m \x1b[1m{label}\x1b[0m{defpart} \x1b[38;5;8m›\x1b[0m "); sys.stdout.flush()
        if rawterm:
            chars=""
            while True:
                k=rawterm.read_key()
                if k in ("\r","\n"): sys.stdout.write("\n"); break
                if k=="\x03": raise KeyboardInterrupt
                if k in ("\x7f","\b"):
                    if chars: chars=chars[:-1]; sys.stdout.write("\b \b")
                    continue
                if k in ("UP","DOWN","ESC"): continue
                if k: chars+=k; sys.stdout.write(k); sys.stdout.flush()
            value=chars
        else:
            try: value=input()
            except EOFError: value=""
        final=value if value!="" else (default if default is not None else "")
        if validate_name:
            if value=="": 
                # reprompt silently like dialoguer (print a moved prompt) - continue without error message
                continue
            if not re.fullmatch(r'[a-z][a-z0-9_]*|[a-z0-9_]+', value) or not re.fullmatch(r'[a-z0-9_]+', value):
                sys.stdout.write(f"\r\x1b[2K\x1b[31m✘\x1b[0m \x1b[31mThe name must be lowercase and contain only letters, digits, and underscores\x1b[0m\r\n"); continue
        sys.stdout.write(f"\x1b[32m✔\x1b[0m \x1b[1m{label}\x1b[0m \x1b[38;5;8m·\x1b[0m \x1b[32m{final}\x1b[0m\n"); sys.stdout.flush()
        return final

def prompt_bindings(rawterm):
    options=[("c",True),("go",True),("java",False),("node",True),("python",True),("rust",True),("swift",True),("zig",False)]
    state=[v for _,v in options]; idx=0
    def render():
        out="\x1b[?25lBindings:\r\n"
        for i,(name,_) in enumerate(options):
            marker=">" if i==idx else " "
            check="x" if state[i] else " "
            out+=f"{marker} [{check}] {name}\r\n"
        sys.stdout.write(out); sys.stdout.flush()
    if rawterm:
        render()
        while True:
            k=rawterm.read_key()
            if k=="UP": idx=(idx-1)%len(options)
            elif k=="DOWN": idx=(idx+1)%len(options)
            elif k==" ": state[idx]=not state[idx]
            elif k in ("\r","\n"): break
            elif k=="\x03": raise KeyboardInterrupt
            else: continue
            # move up 9 lines and rerender
            sys.stdout.write(f"\x1b[{len(options)+1}A"); render()
        sys.stdout.write("\x1b[?25h")
        selected=[name for (name,_),s in zip(options,state) if s]
        sys.stdout.write("Bindings: "+", ".join(selected)+"\r\n")
    else:
        sys.stdout.write("Bindings:\n")
        for name,v in options: sys.stdout.write(f"> [{'x' if v else ' '}] {name}\n")
        try: input()
        except: pass
        selected=[name for (name,v) in options if v]
        sys.stdout.write("Bindings: "+", ".join(selected)+"\n")
    return {name:state[i] for i,(name,_) in enumerate(options)}

