            msg+=f"\nUsage: {bin_name()} <COMMAND>\n\nFor more information, try '--help'.\n"
            sys.stderr.write(msg); return 2
        spec=SPECS[cmd]
        vals,pos=parse_cmd_args(spec, args[1:])
