        # dispatch
        if cmd=="init-config": return cmd_init_config(vals,pos)
        if cmd=="dump-languages": return cmd_dump_languages(vals,pos)
        if cmd=="version": return cmd_version(vals,pos)
        if cmd=="generate": return cmd_generate(vals,pos)
        if cmd=="build": return cmd_build(vals,pos)
        if cmd=="parse": return cmd_parse(vals,pos)
        if cmd=="test": return cmd_test(vals,pos)
        if cmd=="query": return cmd_query(vals,pos)
        if cmd=="highlight": return cmd_highlight(vals,pos)
        if cmd=="tags": return cmd_tags(vals,pos)
        if cmd=="fuzz": return cmd_fuzz(vals,pos)
        if cmd=="playground": return cmd_playground(vals,pos)
        if cmd=="complete": return cmd_complete(vals,pos)
        if cmd=="init": return cmd_init(vals,pos)
        return 0
    except HelpDisplayed:
        return 0
    except ClapError as e:
        sys.stderr.write(str(e)); return 2
    except PanicError as e:
        pid=os.getpid(); sys.stderr.write(f"\nthread 'main' ({pid}) panicked at {e.location}:\n{e.message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"); return 101
