            # nullable
            if not nullable[p.lhs] and seq_nullable(p.rhs): nullable[p.lhs]=True; changed=True
            # first lhs from rhs sequence
            add=set()
            for e in p.rhs:
                if e[0]=='T': add.add(e[1].key); break
                add|=first.get(e[1], set())
                if not nullable.get(e[1], False): break
            if not add<=first[p.lhs]: first[p.lhs]|=add; changed=True
    def first_seq(rhs, look):
        out=set()
