            pi,dot,look=work.pop()
            p=prods[pi]
            if dot < len(p.rhs):
                ek,ev=p.rhs[dot]
                if ek=='N':
                    beta=p.rhs[dot+1:]
                    looks=first_seq(beta, look)
                    for pj in prods_by.get(ev,[]):
