            msg_lines.append("")
            msg_lines.append("Possible interpretations:")
            msg_lines.append("")
            for i,interp in enumerate(interps,1): msg_lines.append(f"  {i}:  {interp}")
            msg_lines.append("")
            msg_lines.append("Possible resolutions:")
            msg_lines.append("")
            for i,res in enumerate(resolutions,1): msg_lines.append(f"  {i}:  {res}")
            msg_lines.append("")
            conflicts_out.append("\n".join(msg_lines))
